window.TXB=window.TXB||{};TXB["svd/2Sa"]={"22:7":"في ضيقي دعوت الرب, وإلى إلهي صرخت, فسمع من هيكله صوتي, وصراخي دخل أذنيه.","22:8":"فارتجت الأرض وارتعشت. أسس السماوات ارتعدت وارتجت, لأنه غضب.","22:9":"صعد دخان من أنفه, ونار من فمه أكلت. جمر اشتعلت منه.","22:10":"طأطأ السماوات ونزل, وضباب تحت رجليه.","22:11":"ركب على كروب, وطار ورئي على أجنحة الريح.","22:12":"جعل الظلمة حوله مظلات, مياها حاشكة وظلام الغمام.","22:13":"من الشعاع قدامه اشتعلت جمر نار.","22:14":"أرعد الرب من السماوات, والعلي أعطى صوته.","22:15":"أرسل سهاما فشتتهم, برقا فأزعجهم.","22:16":"فظهرت أعماق البحر, وانكشفت أسس المسكونة من زجر الرب, من نسمة ريح أنفه.","22:17":"أرسل من العلى فأخذني, نشلني من مياه كثيرة.","22:18":"أنقذني من عدوي القوي, من مبغضي لأنهم أقوى مني.","22:19":"أصابوني في يوم بليتي, وكان الرب سندي.","22:20":"أخرجني إلى الرحب. خلصني لأنه سر بي.","22:21":"يكافئني الرب حسب بري. حسب طهارة يدي يرد علي.","22:22":"لأني حفظت طرق الرب, ولم أعص إلهي.","22:23":"لأن جميع أحكامه أمامي, وفرائضه لا أحيد عنها.","22:24":"وأكون كاملا لديه, وأتحفظ من إثمي.","22:25":"فيرد الرب علي كبري, وكطهارتي أمام عينيه.","22:26":"«مع الرحيم تكون رحيما. مع الرجل الكامل تكون كاملا.","22:27":"مع الطاهر تكون طاهرا, ومع الأعوج تكون ملتويا.","22:28":"وتخلص الشعب البائس, وعيناك على المترفعين فتضعهم.","22:29":"لأنك أنت سراجي يا رب, والرب يضيء ظلمتي.","22:30":"لأني بك اقتحمت جيشا. بإلهي تسورت أسوارا.","22:31":"الله طريقه كامل, وقول الرب نقي. ترس هو لجميع المحتمين به.","22:32":"لأنه من هو إله غير الرب؟ ومن هو صخرة غير إلهنا؟","22:33":"الإله الذي يعززني بالقوة, ويصير طريقي كاملا.","22:34":"الذي يجعل رجلي كالإيل, وعلى مرتفعاتي يقيمني","22:35":"الذي يعلم يدي القتال, فتحنى بذراعي قوس من نحاس.","22:36":"وتجعل لي ترس خلاصك, ولطفك يعظمني.","22:37":"توسع خطواتي تحتي, فلم تتقلقل كعباي.","22:38":"ألحق أعدائي فأهلكهم, ولا أرجع حتى أفنيهم.","22:39":"أفنيهم وأسحقهم فلا يقومون, بل يسقطون تحت رجلي.","22:40":"«تنطقني قوة للقتال, وتصرع القائمين علي تحتي.","22:41":"وتعطيني أقفية أعدائي ومبغضي فأفنيهم.","22:42":"يتطلعون فليس مخلص, إلى الرب فلا يستجيبهم.","22:43":"فأسحقهم كغبار الأرض. مثل طين الأسواق أدقهم وأدوسهم.","22:44":"وتنقذني من مخاصمات شعبي, وتحفظني رأسا للأمم. شعب لم أعرفه يتعبد لي.","22:45":"بنو الغرباء يتذللون لي. من سماع الأذن يسمعون لي.","22:46":"بنو الغرباء يبلون ويزحفون من حصونهم.","22:47":"حي هو الرب, ومبارك صخرتي, ومرتفع إله صخرة خلاصي.","22:48":"الإله المنتقم لي, والمخضع شعوبا تحتي,","22:49":"والذي يخرجني من بين أعدائي, ويرفعني فوق القائمين علي, وينقذني من رجل الظلم.","22:50":"لذلك أحمدك يا رب في الأمم, ولاسمك أرنم.","22:51":"برج خلاص لملكه, والصانع رحمة لمسيحه, لداود ونسله إلى الأبد».","23:1":"فهذه هي كلمات داود الأخيرة: «وحي داود بن يسى, ووحي الرجل القائم في العلا, مسيح إله يعقوب, ومرنم إسرائيل الحلو:","23:2":"روح الرب تكلم بي وكلمته على لساني.","23:3":"قال إله إسرائيل. إلي تكلم صخرة إسرائيل: إذا تسلط على الناس بار يتسلط بخوف الله,","23:4":"وكنور الصباح إذا أشرقت الشمس. كعشب من الأرض في صباح صحو مضيء غب المطر.","23:5":"أليس هكذا بيتي عند الله؟ لأنه وضع لي عهدا أبديا متقنا في كل شيء ومحفوظا, أفلا يثبت كل خلاصي وكل مسرتي؟","23:6":"ولكن بني بليعال جميعهم كشوك مطروح, لأنهم لا يؤخذون بيد.","23:7":"والرجل الذي يمسهم يتسلح بحديد وعصا رمح, فيحترقون بالنار في مكانهم».","23:8":"هذه أسماء الأبطال الذين لداود: يشيب بشبث التحكموني رئيس الثلاثة. هو هز رمحه على ثمان مئة قتلهم دفعة واحدة.","23:9":"وبعده ألعازار بن دودو بن أخوخي, أحد الثلاثة الأبطال الذين كانوا مع داود حينما عيروا الفلسطينيين الذين اجتمعوا هناك للحرب وصعد رجال إسرائيل.","23:10":"أما هو فأقام وضرب الفلسطينيين حتى كلت يده, ولصقت يده بالسيف, وصنع الرب خلاصا عظيما في ذلك اليوم, ورجع الشعب وراءه للنهب فقط.","23:11":"وبعده شمة بن أجي الهراري. فاجتمع الفلسطينيون جيشا, وكانت هناك قطعة حقل مملوءة عدسا, فهرب الشعب من أمام الفلسطينيين.","23:12":"فوقف في وسط القطعة وأنقذها, وضرب الفلسطينيين, فصنع الرب خلاصا عظيما.","23:13":"ونزل الثلاثة من الثلاثين رئيسا وأتوا في الحصاد إلى داود إلى مغارة عدلام, وجيش الفلسطينيين نازل في وادي الرفائيين.","23:14":"وكان داود حينئذ في الحصن, وحفظة الفلسطينيين حينئذ في بيت لحم.","23:15":"فتأوه داود وقال: «من يسقيني ماء من بئر بيت لحم التي عند الباب؟»","23:16":"فشق الأبطال الثلاثة محلة الفلسطينيين واستقوا ماء من بئر بيت لحم التي عند الباب, وحملوه وأتوا به إلى داود, فلم يشأ أن يشربه, بل سكبه للرب,","23:17":"وقال: «حاشا لي يا رب أن أفعل ذلك! هذا دم الرجال الذين خاطروا بأنفسهم». فلم يشأ أن يشربه. هذا ما فعله الثلاثة الأبطال.","23:18":"وأبيشاي أخو يوآب ابن صروية هو رئيس ثلاثة. هذا هز رمحه على ثلاث مئة قتلهم, فكان له اسم بين الثلاثة.","23:19":"ألم يكرم على الثلاثة فكان لهم رئيسا, إلا أنه لم يصل إلى الثلاثة الأول.","23:20":"وبناياهو بن يهوياداع, ابن ذي بأس, كثير الأفعال, من قبصئيل, هو الذي ضرب أسدي موآب, وهو الذي نزل وضرب أسدا في وسط جب يوم الثلج.","23:21":"وهو ضرب رجلا مصريا ذا منظر, وكان بيد المصري رمح, فنزل إليه بعصا وخطف الرمح من يد المصري وقتله برمحه.","23:22":"هذا ما فعله بناياهو بن يهوياداع, فكان له اسم بين الثلاثة الأبطال,","23:23":"وأكرم على الثلاثين, إلا أنه لم يصل إلى الثلاثة. فجعله داود من أصحاب سره.","23:24":"وعسائيل أخو يوآب كان من الثلاثين, وألحانان بن دودو من بيت لحم.","23:25":"وشمة الحرودي, وأليقا الحرودي,","23:26":"وحالص الفلطي, وعيرا بن عقيش التقوعي,","23:27":"وأبيعزر العناثوثي, ومبوناي الحوشاتي,","23:28":"وصلمون الأخوخي, ومهراي النطوفاتي,","23:29":"وخالب بن بعنة النطوفاتي, وإتاي بن ريباي من جبعة بني بنيامين,","23:30":"وبنايا الفرعتوني, وهداي من أودية جاعش,","23:31":"وأبو علبون العرباتي, وعزموت البرحومي,","23:32":"وأليحبا الشعلبوني, ومن بني ياشن: يوناثان.","23:33":"وشمة الهراري, وأخيآم بن شارار الأراري,","23:34":"وأليفلط بن أحسباي ابن المعكي, وأليعام بن أخيتوفل الجيلوني,","23:35":"وحصراي الكرملي, وفعراي الأربي,","23:36":"ويجآل بن ناثان من صوبة, وباني الجادي,","23:37":"وصالق العموني, ونحراي البئيروتي, حامل سلاح يوآب بن صروية,","23:38":"وعيرا اليثري, وجارب اليثري,","23:39":"وأوريا الحثي. الجميع سبعة وثلاثون.","24:1":"وعاد فحمي غضب الرب على إسرائيل, فأهاج عليهم داود قائلا: «امض وأحص إسرائيل ويهوذا».","24:2":"فقال الملك ليوآب رئيس الجيش الذي عنده: «طف في جميع أسباط إسرائيل من دان إلى بئر سبع وعدوا الشعب, فأعلم عدد الشعب».","24:3":"فقال يوآب للملك: «ليزد الرب إلهك الشعب أمثالهم مئة ضعف, وعينا سيدي الملك ناظرتان. ولكن لماذا يسر سيدي الملك بهذا الأمر؟»","24:4":"فاشتد كلام الملك على يوآب وعلى رؤساء الجيش, فخرج يوآب ورؤساء الجيش من عند الملك ليعدوا الشعب, أي إسرائيل.","24:5":"فعبروا الأردن ونزلوا في عروعير عن يمين المدينة التي في وسط وادي جاد وتجاه يعزير.","24:6":"وأتوا إلى جلعاد وإلى أرض تحتيم إلى حدشي, ثم أتوا إلى دان يعن, واستداروا إلى صيدون.","24:7":"ثم أتوا إلى حصن صور وجميع مدن الحويين والكنعانيين, ثم خرجوا إلى جنوبي يهوذا, إلى بئر سبع.","24:8":"وطافوا كل الأرض, وجاءوا في نهاية تسعة أشهر وعشرين يوما إلى أورشليم.","24:9":"فدفع يوآب جملة عدد الشعب إلى الملك, فكان إسرائيل ثمان مئة ألف رجل ذي بأس مستل السيف, ورجال يهوذا خمس مئة ألف رجل.","24:10":"وضرب داود قلبه بعدما عد الشعب. فقال داود للرب: «لقد أخطأت جدا في ما فعلت, والآن يا رب أزل إثم عبدك لأني انحمقت جدا».","24:11":"ولما قام داود صباحا, كان كلام الرب إلى جاد النبي رائي داود قائلا:","24:12":"«اذهب وقل لداود: هكذا قال الرب: ثلاثة أنا عارض عليك, فاختر لنفسك واحدا منها فأفعله بك».","24:13":"فأتى جاد إلى داود وأخبره وقال له: «أتأتي عليك سبع سني جوع في أرضك, أم تهرب ثلاثة أشهر أمام أعدائك وهم يتبعونك, أم يكون ثلاثة أيام وبأ في أرضك؟ فالآن اعرف وانظر ماذا أرد جوابا على مرسلي».","24:14":"فقال داود لجاد: «قد ضاق بي الأمر جدا. فلنسقط في يد الرب, لأن مراحمه كثيرة ولا أسقط في يد إنسان».","24:15":"فجعل الرب وبأ في إسرائيل من الصباح إلى الميعاد, فمات من الشعب من دان إلى بئر سبع سبعون ألف رجل.","24:16":"وبسط الملاك يده على أورشليم ليهلكها, فندم الرب عن الشر, وقال للملاك المهلك الشعب: «كفى! الآن رد يدك». وكان ملاك الرب عند بيدر أرونة اليبوسي.","24:17":"فكلم داود الرب عندما رأى الملاك الضارب الشعب وقال: «ها أنا أخطأت, وأنا أذنبت, وأما هؤلاء الخراف فماذا فعلوا؟ فلتكن يدك علي وعلى بيت أبي».","24:18":"فجاء جاد في ذلك اليوم إلى داود وقال له: «اصعد وأقم للرب مذبحا في بيدر أرونة اليبوسي».","24:19":"فصعد داود حسب كلام جاد كما أمر الرب.","24:20":"فتطلع أرونة ورأى الملك وعبيده يقبلون إليه, فخرج أرونة وسجد للملك على وجهه إلى الأرض.","24:21":"وقال أرونة: «لماذا جاء سيدي الملك إلى عبده؟» فقال داود: «لأشتري منك البيدر لأبني مذبحا للرب فتكف الضربة عن الشعب».","24:22":"فقال أرونة لداود: «فليأخذه سيدي الملك ويصعد ما يحسن في عينيه. انظر. البقر للمحرقة, والنوارج وأدوات البقر حطبا».","24:23":"الكل دفعه أرونة المالك إلى الملك. وقال أرونة للملك: «الرب إلهك يرضى عنك».","24:24":"فقال الملك لأرونة: «لا, بل أشتري منك بثمن, ولا أصعد للرب إلهي محرقات مجانية». فاشترى داود البيدر والبقر بخمسين شاقلا من الفضة.","24:25":"وبنى داود هناك مذبحا للرب وأصعد محرقات وذبائح سلامة, واستجاب الرب من أجل الأرض, فكفت الضربة عن إسرائيل.","4:1":"ولما سمع ابن شاول أن أبنير قد مات في حبرون, ارتخت يداه, وارتاع جميع إسرائيل.","4:2":"وكان لابن شاول رجلان رئيسا غزاة, اسم الواحد بعنة واسم الآخر ركاب, ابنا رمون البئيروتي من بني بنيامين, لأن بئيروت حسبت لبنيامين.","4:3":"وهرب البئيروتيون إلى جتايم وتغربوا هناك إلى هذا اليوم.","4:4":"وكان ليوناثان بن شاول ابن مضروب الرجلين, كان ابن خمس سنين عند مجيء خبر شاول ويوناثان من يزرعيل, فحملته مربيته وهربت. ولما كانت مسرعة لتهرب وقع وصار أعرج. واسمه مفيبوشث.","4:5":"وسار ابنا رمون البئيروتي, ركاب وبعنة, ودخلا عند حر النهار إلى بيت إيشبوشث وهو نائم نومة الظهيرة.","4:6":"فدخلا إلى وسط البيت ليأخذا حنطة, وضرباه في بطنه. ثم أفلت ركاب وبعنة أخوه.","4:7":"فعند دخولهما البيت كان هو مضطجعا على سريره في مخدع نومه, فضرباه وقتلاه وقطعا رأسه, وأخذا رأسه وسارا في طريق العربة الليل كله.","4:8":"وأتيا برأس إيشبوشث إلى داود إلى حبرون, وقالا للملك: «هوذا رأس إيشبوشث بن شاول عدوك الذي كان يطلب نفسك. وقد أعطى الرب لسيدي الملك انتقاما في هذا اليوم من شاول ومن نسله».","4:9":"فأجاب داود ركاب وبعنة أخاه, ابني رمون البئيروتي, وقال لهما: «حي هو الرب الذي فدى نفسي من كل ضيق,","4:10":"إن الذي أخبرني قائلا: هوذا قد مات شاول, وكان في عيني نفسه كمبشر, قبضت عليه وقتلته في صقلغ. ذلك أعطيته بشارة.","4:11":"فكم بالحري إذا كان رجلان باغيان يقتلان رجلا صديقا في بيته, على سريره؟ فالآن أما أطلب دمه من أيديكما, وأنزعكما من الأرض؟»","4:12":"وأمر داود الغلمان فقتلوهما, وقطعوا أيديهما وأرجلهما, وعلقوهما على البركة في حبرون. وأما رأس إيشبوشث فأخذوه ودفنوه في قبر أبنير في حبرون.","5:1":"وجاء جميع أسباط إسرائيل إلى داود, إلى حبرون, وتكلموا قائلين: «هوذا عظمك ولحمك نحن.","5:2":"ومنذ أمس وما قبله, حين كان شاول ملكا علينا, قد كنت أنت تخرج وتدخل إسرائيل. وقد قال لك الرب: أنت ترعى شعبي إسرائيل, وأنت تكون رئيسا على إسرائيل».","5:3":"وجاء جميع شيوخ إسرائيل إلى الملك, إلى حبرون, فقطع الملك داود معهم عهدا في حبرون أمام الرب. ومسحوا داود ملكا على إسرائيل.","5:4":"كان داود ابن ثلاثين سنة حين ملك, وملك أربعين سنة.","5:5":"في حبرون ملك على يهوذا سبع سنين وستة أشهر. وفي أورشليم ملك ثلاثا وثلاثين سنة على جميع إسرائيل ويهوذا.","5:6":"وذهب الملك ورجاله إلى أورشليم, إلى اليبوسيين سكان الأرض. فكلموا داود قائلين: «لا تدخل إلى هنا, ما لم تنزع العميان والعرج». أي لا يدخل داود إلى هنا.","5:7":"وأخذ داود حصن صهيون, هي مدينة داود.","5:8":"وقال داود في ذلك اليوم: «إن الذي يضرب اليبوسيين ويبلغ إلى القناة والعرج والعمي المبغضين من نفس داود». لذلك يقولون: «لا يدخل البيت أعمى أو أعرج».","5:9":"وأقام داود في الحصن وسماه «مدينة داود». وبنى داود مستديرا من القلعة فداخلا.","5:10":"وكان داود يتزايد متعظما, والرب إله الجنود معه.","5:11":"وأرسل حيرام ملك صور رسلا إلى داود, وخشب أرز ونجارين وبنائين فبنوا لداود بيتا.","5:12":"وعلم داود أن الرب قد أثبته ملكا على إسرائيل, وأنه قد رفع ملكه من أجل شعبه إسرائيل.","5:13":"وأخذ داود أيضا سراري ونساء من أورشليم بعد مجيئه من حبرون, فولد أيضا لداود بنون وبنات.","5:14":"وهذه أسماء الذين ولدوا له في أورشليم: شموع وشوباب وناثان وسليمان,","5:15":"ويبحار وأليشوع ونافج ويافيع,","5:16":"وأليشمع وأليداع وأليفلط.","5:17":"وسمع الفلسطينيون أنهم قد مسحوا داود ملكا على إسرائيل, فصعد جميع الفلسطينيين ليفتشوا على داود. ولما سمع داود نزل إلى الحصن.","5:18":"وجاء الفلسطينيون وانتشروا في وادي الرفائيين.","5:19":"وسأل داود من الرب قائلا: «أأصعد إلى الفلسطينيين؟ أتدفعهم ليدي؟» فقال الرب لداود: «اصعد, لأني دفعا أدفع الفلسطينيين ليدك».","5:20":"فجاء داود إلى بعل فراصيم وضربهم داود هناك, وقال: «قد اقتحم الرب أعدائي أمامي كاقتحام المياه». لذلك دعى اسم ذلك الموضع «بعل فراصيم».","5:21":"وتركوا هناك أصنامهم فنزعها داود ورجاله.","5:22":"ثم عاد الفلسطينيون فصعدوا أيضا وانتشروا في وادي الرفائيين.","5:23":"فسأل داود من الرب, فقال: «لا تصعد, بل در من ورائهم, وهلم عليهم مقابل أشجار البكا,","5:24":"وعندما تسمع صوت خطوات في رؤوس أشجار البكا, حينئذ احترص, لأنه إذ ذاك يخرج الرب أمامك لضرب محلة الفلسطينيين».","5:25":"ففعل داود كذلك كما أمره الرب, وضرب الفلسطينيين من جبع إلى مدخل جازر.","6:1":"وجمع داود أيضا جميع المنتخبين في إسرائيل, ثلاثين ألفا.","6:2":"وقام داود وذهب هو وجميع الشعب الذي معه من بعلة يهوذا, ليصعدوا من هناك تابوت الله, الذي يدعى عليه بالاسم, اسم رب الجنود, الجالس على الكروبيم.","6:3":"فأركبوا تابوت الله على عجلة جديدة, وحملوه من بيت أبيناداب الذي في الأكمة. وكان عزة وأخيو, ابنا أبيناداب يسوقان العجلة الجديدة.","6:4":"فأخذوها من بيت أبيناداب الذي في الأكمة مع تابوت الله. وكان أخيو يسير أمام التابوت,","6:5":"وداود وكل بيت إسرائيل يلعبون أمام الرب بكل أنواع الآلات من خشب السرو, بالعيدان وبالرباب وبالدفوف وبالجنوك وبالصنوج.","6:6":"ولما انتهوا إلى بيدر ناخون مد عزة يده إلى تابوت الله وأمسكه, لأن الثيران انشمصت.","6:7":"فحمي غضب الرب على عزة, وضربه الله هناك لأجل غفله, فمات هناك لدى تابوت الله.","6:8":"فاغتاظ داود لأن الرب اقتحم عزة اقتحاما, وسمى ذلك الموضع «فارص عزة» إلى هذا اليوم.","6:9":"وخاف داود من الرب في ذلك اليوم وقال: «كيف يأتي إلي تابوت الرب؟»","6:10":"ولم يشأ داود أن ينقل تابوت الرب إليه, إلى مدينة داود, فمال به داود إلى بيت عوبيد أدوم الجتي.","6:11":"وبقي تابوت الرب في بيت عوبيد أدوم الجتي ثلاثة أشهر. وبارك الرب عوبيد أدوم وكل بيته.","6:12":"فأخبر الملك داود وقيل له: «قد بارك الرب بيت عوبيد أدوم, وكل ما له بسبب تابوت الله». فذهب داود وأصعد تابوت الله من بيت عوبيد أدوم إلى مدينة داود بفرح.","6:13":"وكان كلما خطا حاملوا تابوت الرب ست خطوات يذبح ثورا وعجلا معلوفا.","6:14":"وكان داود يرقص بكل قوته أمام الرب. وكان داود متنطقا بأفود من كتان.","6:15":"فأصعد داود وجميع بيت إسرائيل تابوت الرب بالهتاف وبصوت البوق.","6:16":"ولما دخل تابوت الرب مدينة داود, أشرفت ميكال بنت شاول من الكوة ورأت الملك داود يطفر ويرقص أمام الرب, فاحتقرته في قلبها.","6:17":"فأدخلوا تابوت الرب وأوقفوه في مكانه في وسط الخيمة التي نصبها له داود. وأصعد داود محرقات أمام الرب وذبائح سلامة.","6:18":"ولما انتهى داود من إصعاد المحرقات وذبائح السلامة بارك الشعب باسم رب الجنود.","6:19":"وقسم على جميع الشعب, على كل جمهور إسرائيل رجالا ونساء, على كل واحد رغيف خبز وكأس خمر وقرص زبيب. ثم ذهب كل الشعب كل واحد إلى بيته,","6:20":"ورجع داود ليبارك بيته. فخرجت ميكال بنت شاول لاستقبال داود, وقالت: «ما كان أكرم ملك إسرائيل اليوم, حيث تكشف اليوم في أعين إماء عبيده كما يتكشف أحد السفهاء».","6:21":"فقال داود لميكال: «إنما أمام الرب الذي اختارني دون أبيك ودون كل بيته ليقيمني رئيسا على شعب الرب إسرائيل, فلعبت أمام الرب.","6:22":"وإني أتصاغر دون ذلك وأكون وضيعا في عيني نفسي, وأما عند الإماء التي ذكرت فأتمجد».","6:23":"ولم يكن لميكال بنت شاول ولد إلى يوم موتها.","7:1":"وكان لما سكن الملك في بيته, وأراحه الرب من كل الجهات من جميع أعدائه,","7:2":"أن الملك قال لناثان النبي: «انظر. إني ساكن في بيت من أرز, وتابوت الله ساكن داخل الشقق».","7:3":"فقال ناثان للملك: «اذهب افعل كل ما بقلبك, لأن الرب معك».","7:4":"وفي تلك الليلة كان كلام الرب إلى ناثان قائلا:","7:5":"«اذهب وقل لعبدي داود: هكذا قال الرب: أأنت تبني لي بيتا لسكناي؟","7:6":"لأني لم أسكن في بيت منذ يوم أصعدت بني إسرائيل من مصر إلى هذا اليوم, بل كنت أسير في خيمة وفي مسكن.","7:7":"في كل ما سرت مع جميع بني إسرائيل, هل تكلمت بكلمة إلى أحد قضاة إسرائيل الذين أمرتهم أن يرعوا شعبي إسرائيل قائلا: لماذا لم تبنوا لي بيتا من الأرز؟","7:8":"والآن فهكذا تقول لعبدي داود: هكذا قال رب الجنود: أنا أخذتك من المربض من وراء الغنم لتكون رئيسا على شعبي إسرائيل.","7:9":"وكنت معك حيثما توجهت, وقرضت جميع أعدائك من أمامك, وعملت لك اسما عظيما كاسم العظماء الذين في الأرض.","7:10":"وعينت مكانا لشعبي إسرائيل وغرسته, فسكن في مكانه, ولا يضطرب بعد, ولا يعود بنو الإثم يذللونه كما في الأول,","1:1":"وكان بعد موت شاول ورجوع داود من مضاربة العمالقة, أن داود أقام في صقلغ يومين.","1:2":"وفي اليوم الثالث إذا برجل أتى من المحلة من عند شاول وثيابه ممزقة وعلى رأسه تراب. فلما جاء إلى داود خر إلى الأرض وسجد.","1:3":"فقال له داود: «من أين أتيت؟» فقال له: «من محلة إسرائيل نجوت».","1:4":"فقال له داود: «كيف كان الأمر؟ أخبرني». فقال: «إن الشعب قد هرب من القتال, وسقط أيضا كثيرون من الشعب وماتوا, ومات شاول ويوناثان ابنه أيضا».","1:5":"فقال داود للغلام الذي أخبره: «كيف عرفت أنه قد مات شاول ويوناثان ابنه؟»","1:6":"فقال الغلام الذي أخبره: «اتفق أني كنت في جبل جلبوع وإذا شاول يتوكأ على رمحه, وإذا بالمركبات والفرسان يشدون وراءه.","1:7":"فالتفت إلى ورائه فرآني ودعاني فقلت: هأنذا.","1:8":"فقال لي: من أنت؟ فقلت له: عماليقي أنا.","1:9":"فقال لي: قف علي واقتلني لأنه قد اعتراني الدوار, لأن كل نفسي بعد في.","1:10":"فوقفت عليه وقتلته لأني علمت أنه لا يعيش بعد سقوطه, وأخذت الإكليل الذي على رأسه والسوار الذي على ذراعه وأتيت بهما إلى سيدي ههنا».","1:11":"فأمسك داود ثيابه ومزقها, وكذا جميع الرجال الذين معه.","1:12":"وندبوا وبكوا وصاموا إلى المساء على شاول وعلى يوناثان ابنه, وعلى شعب الرب وعلى بيت إسرائيل لأنهم سقطوا بالسيف.","1:13":"ثم قال داود للغلام الذي أخبره: «من أين أنت؟» فقال: «أنا ابن رجل غريب, عماليقي».","1:14":"فقال له داود: «كيف لم تخف أن تمد يدك لتهلك مسيح الرب؟».","1:15":"ثم دعا داود واحدا من الغلمان وقال: «تقدم. أوقع به». فضربه فمات.","1:16":"فقال له داود: «دمك على رأسك لأن فمك شهد عليك قائلا: أنا قتلت مسيح الرب».","1:17":"ورثا داود بهذه المرثاة شاول ويوناثان ابنه,","1:18":"وقال أن يتعلم بنو يهوذا «نشيد القوس». هوذا ذلك مكتوب في سفر ياشر:","1:19":"«الظبي يا إسرائيل مقتول على شوامخك. كيف سقط الجبابرة!","1:20":"لا تخبروا في جت. لا تبشروا في أسواق أشقلون, لئلا تفرح بنات الفلسطينيين, لئلا تشمت بنات الغلف.","1:21":"يا جبال جلبوع لا يكن طل ولا مطر عليكن, ولا حقول تقدمات, لأنه هناك طرح مجن الجبابرة, مجن شاول بلا مسح بالدهن.","1:22":"من دم القتلى, من شحم الجبابرة لم ترجع قوس يوناثان إلى الوراء, وسيف شاول لم يرجع خائبا.","1:23":"شاول ويوناثان المحبوبان والحلوان في حياتهما لم يفترقا في موتهما. أخف من النسور وأشد من الأسود.","1:24":"يا بنات إسرائيل, ابكين شاول الذي ألبسكن قرمزا بالتنعم, وجعل حلي الذهب على ملابسكن.","1:25":"كيف سقط الجبابرة في وسط الحرب! يوناثان على شوامخك مقتول.","1:26":"قد تضايقت عليك يا أخي يوناثان. كنت حلوا لي جدا. محبتك لي أعجب من محبة النساء.","1:27":"كيف سقط الجبابرة وبادت آلات الحرب!».","2:1":"وكان بعد ذلك أن داود سأل الرب قائلا: «أأصعد إلى إحدى مدائن يهوذا؟» فقال له الرب: «اصعد». فقال داود: «إلى أين أصعد؟» فقال: «إلى حبرون».","2:2":"فصعد داود إلى هناك هو وامرأتاه أخينوعم اليزرعيلية وأبيجايل امرأة نابال الكرملي.","2:3":"وأصعد داود رجاله الذين معه, كل واحد وبيته, وسكنوا في مدن حبرون.","2:4":"وأتى رجال يهوذا ومسحوا هناك داود ملكا على بيت يهوذا. وأخبروا داود قائلين: «إن رجال يابيش جلعاد هم الذين دفنوا شاول».","2:5":"فأرسل داود رسلا إلى أهل يابيش جلعاد يقول لهم: «مباركون أنتم من الرب, إذ قد فعلتم هذا المعروف بسيدكم شاول فدفنتموه.","2:6":"والآن ليصنع الرب معكم إحسانا وحقا, وأنا أيضا أفعل معكم هذا الخير لأنكم فعلتم هذا الأمر.","2:7":"والآن فلتتشدد أيديكم وكونوا ذوي بأس, لأنه قد مات سيدكم شاول, وإياي مسح بيت يهوذا ملكا عليهم».","2:8":"وأما أبنير بن نير, رئيس جيش شاول, فأخذ إيشبوشث بن شاول وعبر به إلى محنايم,","2:9":"وجعله ملكا على جلعاد وعلى الأشوريين وعلى يزرعيل وعلى أفرايم وعلى بنيامين وعلى كل إسرائيل.","2:10":"وكان إيشبوشث بن شاول ابن أربعين سنة حين ملك على إسرائيل, وملك سنتين. وأما بيت يهوذا فإنما اتبعوا داود.","2:11":"وكانت المدة التي ملك فيها داود في حبرون على بيت يهوذا سبع سنين وستة أشهر.","2:12":"وخرج أبنير بن نير وعبيد إيشبوشث بن شاول من محنايم إلى جبعون.","2:13":"وخرج يوآب بن صروية وعبيد داود, فالتقوا جميعا على بركة جبعون, وجلسوا هؤلاء على البركة من هنا وهؤلاء على البركة من هناك.","2:14":"فقال أبنير ليوآب: «ليقم الغلمان ويتكافحوا أمامنا». فقال يوآب: «ليقوموا».","2:15":"فقاموا وعبروا بالعدد, اثنا عشر لأجل بنيامين وإيشبوشث بن شاول, واثنا عشر من عبيد داود.","2:16":"وأمسك كل واحد برأس صاحبه وضرب سيفه في جنب صاحبه وسقطوا جميعا. فدعي ذلك الموضع «حلقث هصوريم», التي هي في جبعون.","2:17":"وكان القتال شديدا جدا في ذلك اليوم, وانكسر أبنير ورجال إسرائيل أمام عبيد داود.","2:18":"وكان هناك بنو صروية الثلاثة: يوآب وأبيشاي وعسائيل. وكان عسائيل خفيف الرجلين كظبي البر.","2:19":"فسعى عسائيل وراء أبنير, ولم يمل في السير يمنة ولا يسرة من وراء أبنير.","2:20":"فالتفت أبنير إلى ورائه وقال: «أأنت عسائيل؟» فقال: «أنا هو».","2:21":"فقال له أبنير: «مل إلى يمينك أو إلى يسارك واقبض على أحد الغلمان وخذ لنفسك سلبه». فلم يشأ عسائيل أن يميل من ورائه.","2:22":"ثم عاد أبنير وقال لعسائيل: «مل من ورائي. لماذا أضربك إلى الأرض؟ فكيف أرفع وجهي لدى يوآب أخيك؟»","2:23":"فأبى أن يميل, فضربه أبنير بزج الرمح في بطنه, فخرج الرمح من خلفه, فسقط هناك ومات في مكانه. وكان كل من يأتي إلى الموضع الذي سقط فيه عسائيل ومات يقف.","2:24":"وسعى يوآب وأبيشاي وراء أبنير, وغابت الشمس عندما أتيا إلى تل أمة الذي تجاه جيح في طريق برية جبعون.","2:25":"فاجتمع بنو بنيامين وراء أبنير وصاروا جماعة واحدة, ووقفوا على رأس تل واحد.","2:26":"فنادى أبنير يوآب وقال: «هل إلى الأبد يأكل السيف؟ ألم تعلم أنها تكون مرارة في الأخير؟ فحتى متى لا تقول للشعب أن يرجعوا من وراء إخوتهم؟»","2:27":"فقال يوآب: «حي هو الله, إنه لو لم تتكلم لكان الشعب في الصباح قد صعد كل واحد من وراء أخيه».","2:28":"وضرب يوآب بالبوق فوقف جميع الشعب ولم يسعوا بعد وراء إسرائيل ولا عادوا إلى المحاربة.","2:29":"فسار أبنير ورجاله في العربة ذلك الليل كله وعبروا الأردن, وساروا في كل الشعب وجاءوا إلى محنايم.","2:30":"ورجع يوآب من وراء أبنير وجمع كل الشعب. وفقد من عبيد داود تسعة عشر رجلا وعسائيل.","2:31":"وضرب عبيد داود من بنيامين ومن رجال أبنير, فمات ثلاث مئين وستون رجلا.","2:32":"ورفعوا عسائيل ودفنوه في قبر أبيه الذي في بيت لحم. وسار يوآب ورجاله الليل كله وأصبحوا في حبرون.","3:1":"وكانت الحرب طويلة بين بيت شاول وبيت داود, وكان داود يذهب يتقوى, وبيت شاول يذهب يضعف.","3:2":"وولد لداود بنون في حبرون. وكان بكره أمنون من أخينوعم اليزرعيلية,","3:3":"وثانيه كيلآب من أبيجايل امرأة نابال الكرملي, والثالث أبشالوم ابن معكة بنت تلماي ملك جشور,","3:4":"والرابع أدونيا ابن حجيث, والخامس شفطيا ابن أبيطال,","3:5":"والسادس يثرعام من عجلة امرأة داود. هؤلاء ولدوا لداود في حبرون.","3:6":"وكان في وقوع الحرب بين بيت شاول وبيت داود, أن أبنير تشدد لأجل بيت شاول.","3:7":"وكانت لشاول سرية اسمها رصفة بنت أية. فقال إيشبوشث لأبنير: «لماذا دخلت إلى سرية أبي؟»","3:8":"فاغتاظ أبنير جدا من كلام إيشبوشث وقال: «ألعلي رأس كلب ليهوذا؟ اليوم أصنع معروفا مع بيت شاول أبيك, مع إخوته ومع أصحابه, ولم أسلمك ليد داود, وتطالبني اليوم بإثم المرأة!","3:9":"هكذا يصنع الله بأبنير وهكذا يزيده, إنه كما حلف الرب لداود كذلك أصنع له","3:10":"لنقل المملكة من بيت شاول, وإقامة كرسي داود على إسرائيل وعلى يهوذا من دان إلى بئر سبع».","3:11":"ولم يقدر بعد أن يجاوب أبنير بكلمة لأجل خوفه منه.","3:12":"فأرسل أبنير من فوره رسلا إلى داود قائلا: «لمن هي الأرض؟ يقولون: اقطع عهدك معي, وهوذا يدي معك لرد جميع إسرائيل إليك».","3:13":"فقال: «حسنا. أنا أقطع معك عهدا, إلا إني أطلب منك أمرا واحدا, وهو أن لا ترى وجهي ما لم تأت أولا بميكال بنت شاول حين تأتي لترى وجهي».","3:14":"وأرسل داود رسلا إلى إيشبوشث بن شاول يقول: «أعطني امرأتي ميكال التي خطبتها لنفسي بمئة غلفة من الفلسطينيين».","3:15":"فأرسل إيشبوشث وأخذها من عند رجلها, من فلطيئيل بن لايش.","3:16":"وكان رجلها يسير معها ويبكي وراءها إلى بحوريم. فقال له أبنير: «اذهب. ارجع». فرجع.","3:17":"وكان كلام أبنير إلى شيوخ إسرائيل قائلا: «قد كنتم منذ أمس وما قبله تطلبون داود ليكون ملكا عليكم.","3:18":"فالآن افعلوا, لأن الرب كلم داود قائلا: إني بيد داود عبدي أخلص شعبي إسرائيل من يد الفلسطينيين ومن أيدي جميع أعدائهم».","3:19":"وتكلم أبنير أيضا في مسامع بنيامين, وذهب أبنير ليتكلم في سماع داود أيضا في حبرون, بكل ما حسن في أعين إسرائيل وفي أعين جميع بيت بنيامين.","3:20":"فجاء أبنير إلى داود إلى حبرون ومعه عشرون رجلا. فصنع داود لأبنير وللرجال الذين معه وليمة.","3:21":"وقال أبنير لداود: «أقوم وأذهب وأجمع إلى سيدي الملك جميع إسرائيل, فيقطعون معك عهدا, وتملك حسب كل ما تشتهي نفسك». فأرسل داود أبنير فذهب بسلام.","3:22":"وإذا بعبيد داود ويوآب قد جاءوا من الغزو وأتوا بغنيمة كثيرة معهم, ولم يكن أبنير مع داود في حبرون, لأنه كان قد أرسله فذهب بسلام.","3:23":"وجاء يوآب وكل الجيش الذي معه. فأخبروا يوآب قائلين: «قد جاء أبنير بن نير إلى الملك فأرسله, فذهب بسلام».","3:24":"فدخل يوآب إلى الملك وقال: «ماذا فعلت؟ هوذا قد جاء أبنير إليك. لماذا أرسلته فذهب؟","3:25":"أنت تعلم أبنير بن نير أنه إنما جاء ليملقك, وليعلم خروجك ودخولك وليعلم كل ما تصنع».","3:26":"ثم خرج يوآب من عند داود وأرسل رسلا وراء أبنير, فردوه من بئر السيرة وداود لا يعلم.","3:27":"ولما رجع أبنير إلى حبرون, مال به يوآب إلى وسط الباب ليكلمه سرا, وضربه هناك في بطنه فمات بدم عسائيل أخيه.","3:28":"فسمع داود بعد ذلك فقال: «إني بريء أنا ومملكتي لدى الرب إلى الأبد من دم أبنير بن نير.","3:29":"فليحل على رأس يوآب وعلى كل بيت أبيه, ولا ينقطع من بيت يوآب ذو سيل وأبرص وعاكز على العكازة وساقط بالسيف ومحتاج الخبز».","3:30":"فقتل يوآب وأبيشاي أخوه أبنير, لأنه قتل عسائيل أخاهما في جبعون في الحرب.","3:31":"فقال داود ليوآب ولجميع الشعب الذي معه: «مزقوا ثيابكم وتنطقوا بالمسوح والطموا أمام أبنير». وكان داود الملك يمشي وراء النعش.","3:32":"ودفنوا أبنير في حبرون. ورفع الملك صوته وبكى على قبر أبنير, وبكى جميع الشعب.","3:33":"ورثا الملك أبنير وقال: «هل كموت أحمق يموت أبنير؟","3:34":"يداك لم تكونا مربوطتين, ورجلاك لم توضعا في سلاسل نحاس. كالسقوط أمام بني الإثم سقطت». وعاد جميع الشعب يبكون عليه.","3:35":"وجاء جميع الشعب ليطعموا داود خبزا, وكان بعد نهار. فحلف داود قائلا: «هكذا يفعل لي الله وهكذا يزيد, إن كنت أذوق خبزا أو شيئا آخر قبل غروب الشمس».","3:36":"فعرف جميع الشعب وحسن في أعينهم, كما أن كل ما صنع الملك كان حسنا في أعين جميع الشعب.","3:37":"وعلم كل الشعب وجميع إسرائيل في ذلك اليوم أنه لم يكن من الملك قتل أبنير بن نير.","3:38":"وقال الملك لعبيده: «ألا تعلمون أن رئيسا وعظيما سقط اليوم في إسرائيل؟","3:39":"وأنا اليوم ضعيف وممسوح ملكا, وهؤلاء الرجال بنو صروية أقوى مني. يجازي الرب فاعل الشر كشره».","7:11":"ومنذ يوم أقمت فيه قضاة على شعبي إسرائيل. وقد أرحتك من جميع أعدائك. والرب يخبرك أن الرب يصنع لك بيتا.","7:12":"متى كملت أيامك واضطجعت مع آبائك, أقيم بعدك نسلك الذي يخرج من أحشائك وأثبت مملكته.","7:13":"هو يبني بيتا لاسمي, وأنا أثبت كرسي مملكته إلى الأبد.","7:14":"أنا أكون له أبا وهو يكون لي ابنا. إن تعوج أؤدبه بقضيب الناس وبضربات بني آدم.","7:15":"ولكن رحمتي لا تنزع منه كما نزعتها من شاول الذي أزلته من أمامك.","7:16":"ويأمن بيتك ومملكتك إلى الأبد أمامك. كرسيك يكون ثابتا إلى الأبد».","7:17":"فحسب جميع هذا الكلام وحسب كل هذه الرؤيا كذلك كلم ناثان داود.","7:18":"فدخل الملك داود وجلس أمام الرب وقال: «من أنا يا سيدي الرب؟ وما هو بيتي حتى أوصلتني إلى ههنا؟","7:19":"وقل هذا أيضا في عينيك يا سيدي الرب, فتكلمت أيضا من جهة بيت عبدك إلى زمان طويل, وهذه عادة الإنسان يا سيدي الرب.","7:20":"وبماذا يعود داود يكلمك وأنت قد عرفت عبدك يا سيدي الرب؟","7:21":"فمن أجل كلمتك وحسب قلبك فعلت هذه العظائم كلها لتعرف عبدك.","7:22":"لذلك قد عظمت أيها الرب الإله, لأنه ليس مثلك وليس إله غيرك حسب كل ما سمعناه بآذاننا.","7:23":"وأية أمة على الأرض مثل شعبك إسرائيل الذي سار الله ليفتديه لنفسه شعبا, ويجعل له اسما, ويعمل لكم العظائم والتخاويف لأرضك أمام شعبك الذي افتديته لنفسك من مصر, من الشعوب وآلهتهم.","7:24":"وثبت لنفسك شعبك إسرائيل, شعبا لنفسك إلى الأبد, وأنت يا رب صرت لهم إلها.","7:25":"والآن أيها الرب الإله أقم إلى الأبد الكلام الذي تكلمت به عن عبدك وعن بيته, وافعل كما نطقت.","7:26":"وليتعظم اسمك إلى الأبد, فيقال: رب الجنود إله على إسرائيل. وليكن بيت عبدك داود ثابتا أمامك.","7:27":"لأنك أنت يا رب الجنود إله إسرائيل قد أعلنت لعبدك قائلا: إني أبني لك بيتا, لذلك وجد عبدك في قلبه أن يصلي لك هذه الصلاة.","7:28":"والآن يا سيدي الرب أنت هو الله وكلامك هو حق, وقد كلمت عبدك بهذا الخير.","7:29":"فالآن ارتض وبارك بيت عبدك ليكون إلى الأبد أمامك, لأنك أنت يا سيدي الرب قد تكلمت. فليبارك بيت عبدك ببركتك إلى الأبد».","8:1":"وبعد ذلك ضرب داود الفلسطينيين وذللهم, وأخذ داود «زمام القصبة» من يد الفلسطينيين.","8:2":"وضرب الموآبيين وقاسهم بالحبل. أضجعهم على الأرض, فقاس بحبلين للقتل وبحبل للاستحياء. وصار الموآبيون عبيدا لداود يقدمون هدايا.","8:3":"وضرب داود هدد عزر بن رحوب ملك صوبة حين ذهب ليرد سلطته عند نهر الفرات.","8:4":"فأخذ داود منه ألفا وسبع مئة فارس وعشرين ألف راجل. وعرقب داود جميع خيل المركبات وأبقى منها مئة مركبة.","8:5":"فجاء أرام دمشق لنجدة هدد عزر ملك صوبة, فضرب داود من أرام اثنين وعشرين ألف رجل.","8:6":"وجعل داود محافظين في أرام دمشق, وصار الأراميون لداود عبيدا يقدمون هدايا. وكان الرب يخلص داود حيثما توجه.","8:7":"وأخذ داود أتراس الذهب التي كانت على عبيد هدد عزر وأتى بها إلى أورشليم.","8:8":"ومن باطح ومن بيروثاي, مدينتي هدد عزر, أخذ الملك داود نحاسا كثيرا جدا.","8:9":"وسمع توعي ملك حماة أن داود قد ضرب كل جيش هدد عزر,","8:10":"فأرسل توعي يورام ابنه إلى الملك داود ليسأل عن سلامته ويباركه لأنه حارب هدد عزر وضربه, لأن هدد عزر كانت له حروب مع توعي. وكان بيده آنية فضة وآنية ذهب وآنية نحاس.","8:11":"وهذه أيضا قدسها الملك داود للرب مع الفضة والذهب الذي قدسه من جميع الشعوب الذين أخضعهم","8:12":"من أرام, ومن موآب, ومن بني عمون, ومن الفلسطينيين, ومن عماليق, ومن غنيمة هدد عزر بن رحوب ملك صوبة.","8:13":"ونصب داود تذكارا عند رجوعه من ضربه ثمانية عشر ألفا من أرام في وادي الملح.","8:14":"وجعل في أدوم محافظين. وضع محافظين في أدوم كلها. وكان جميع الأدوميين عبيدا لداود. وكان الرب يخلص داود حيثما توجه.","8:15":"وملك داود على جميع إسرائيل. وكان داود يجري قضاء وعدلا لكل شعبه.","8:16":"وكان يوآب ابن صروية على الجيش, ويهوشافاط بن أخيلود مسجلا,","8:17":"وصادوق بن أخيطوب وأخيمالك بن أبياثار كاهنين, وسرايا كاتبا,","8:18":"وبناياهو بن يهوياداع على الجلادين والسعاة, وبنو داود كانوا كهنة.","9:1":"وقال داود: «هل يوجد بعد أحد قد بقي من بيت شاول, فأصنع معه معروفا من أجل يوناثان؟»","9:2":"وكان لبيت شاول عبد اسمه صيبا, فاستدعوه إلى داود, وقال له الملك: «أأنت صيبا؟» فقال: «عبدك».","9:3":"فقال الملك: «ألا يوجد بعد أحد لبيت شاول فأصنع معه إحسان الله؟» فقال صيبا للملك: «بعد ابن ليوناثان أعرج الرجلين».","9:4":"فقال له الملك: «أين هو؟» فقال صيبا للملك: «هوذا هو في بيت ماكير بن عميئيل في لودبار».","9:5":"فأرسل الملك داود وأخذه من بيت ماكير بن عميئيل من لودبار.","9:6":"فجاء مفيبوشث بن يوناثان بن شاول إلى داود وخر على وجهه وسجد, فقال داود: «يا مفيبوشث». فقال: «هأنذا عبدك».","9:7":"فقال له داود: «لا تخف. فإني لأعملن معك معروفا من أجل يوناثان أبيك, وأرد لك كل حقول شاول أبيك, وأنت تأكل خبزا على مائدتي دائما».","9:8":"فسجد وقال: «من هو عبدك حتى تلتفت إلى كلب ميت مثلي؟».","9:9":"ودعا الملك صيبا غلام شاول وقال له: «كل ما كان لشاول ولكل بيته قد دفعته لابن سيدك.","9:10":"فتشتغل له في الأرض أنت وبنوك وعبيدك, وتستغل ليكون لابن سيدك خبز ليأكل. ومفيبوشث ابن سيدك يأكل دائما خبزا على مائدتي». وكان لصيبا خمسة عشر ابنا وعشرون عبدا.","9:11":"فقال صيبا للملك: «حسب كل ما يأمر به سيدي الملك عبده كذلك يصنع عبدك». «فيأكل مفيبوشث على مائدتي كواحد من بني الملك».","9:12":"وكان لمفيبوشث ابن صغير اسمه ميخا. وكان جميع ساكني بيت صيبا عبيدا لمفيبوشث.","9:13":"فسكن مفيبوشث في أورشليم, لأنه كان يأكل دائما على مائدة الملك. وكان أعرج من رجليه كلتيهما.","10:1":"وكان بعد ذلك أن ملك بني عمون مات, وملك حانون ابنه عوضا عنه.","10:2":"فقال داود: «أصنع معروفا مع حانون بن ناحاش كما صنع أبوه معي معروفا». فأرسل داود بيد عبيده يعزيه عن أبيه. فجاء عبيد داود إلى أرض بني عمون.","10:3":"فقال رؤساء بني عمون لحانون سيدهم: «هل يكرم داود أباك في عينيك حتى أرسل إليك معزين؟ أليس لأجل فحص المدينة وتجسسها وقلبها, أرسل داود عبيده إليك؟»","10:4":"فأخذ حانون عبيد داود وحلق أنصاف لحاهم, وقص ثيابهم من الوسط إلى أستاههم, ثم أطلقهم.","10:5":"ولما أخبروا داود أرسل للقائهم, لأن الرجال كانوا خجلين جدا. وقال الملك: «أقيموا في أريحا حتى تنبت لحاكم ثم ارجعوا».","10:6":"ولما رأى بنو عمون أنهم قد أنتنوا عند داود, أرسل بنو عمون واستأجروا أرام بيت رحوب وأرام صوبا, عشرين ألف راجل, ومن ملك معكة ألف رجل, ورجال طوب اثني عشر ألف رجل.","10:7":"فلما سمع داود أرسل يوآب وكل جيش الجبابرة.","10:8":"وخرج بنو عمون واصطفوا للحرب عند مدخل الباب, وكان أرام صوبا ورحوب ورجال طوب ومعكة وحدهم في الحقل.","10:9":"فلما رأى يوآب أن مقدمة الحرب كانت نحوه من قدام ومن وراء, اختار من جميع منتخبي إسرائيل وصفهم للقاء أرام","10:10":"وسلم بقية الشعب ليد أخيه أبيشاي, فصفهم للقاء بني عمون.","10:11":"وقال: «إن قوي أرام علي تكون لي منجدا, وإن قوي عليك بنو عمون أذهب لنجدتك.","10:12":"تجلد ولنتشدد من أجل شعبنا ومن أجل مدن إلهنا, والرب يفعل ما يحسن في عينيه».","10:13":"فتقدم يوآب والشعب الذين معه لمحاربة أرام فهربوا من أمامه.","10:14":"ولما رأى بنو عمون أنه قد هرب أرام, هربوا من أمام أبيشاي ودخلوا المدينة. فرجع يوآب عن بني عمون وأتى إلى أورشليم.","10:15":"ولما رأى أرام أنهم قد انكسروا أمام إسرائيل, اجتمعوا معا.","10:16":"وأرسل هدر عزر فأبرز أرام الذي في عبر النهر, فأتوا إلى حيلام وأمامهم شوبك رئيس جيش هدر عزر.","10:17":"ولما أخبر داود, جمع كل إسرائيل وعبر الأردن وجاء إلى حيلام, فاصطف أرام للقاء داود وحاربوه.","10:18":"وهرب أرام من أمام إسرائيل, وقتل داود من أرام سبع مئة مركبة وأربعين ألف فارس, وضرب شوبك رئيس جيشه فمات هناك.","10:19":"ولما رأى جميع الملوك, عبيد هدر عزر أنهم انكسروا أمام إسرائيل, صالحوا إسرائيل واستعبدوا لهم, وخاف أرام أن ينجدوا بني عمون بعد.","11:1":"وكان عند تمام السنة, في وقت خروج الملوك, أن داود أرسل يوآب وعبيده معه وجميع إسرائيل, فأخربوا بني عمون وحاصروا ربة. وأما داود فأقام في أورشليم.","11:2":"وكان في وقت المساء أن داود قام عن سريره وتمشى على سطح بيت الملك, فرأى من على السطح امرأة تستحم. وكانت المرأة جميلة المنظر جدا.","11:3":"فأرسل داود وسأل عن المرأة, فقال واحد: «أليست هذه بثشبع بنت أليعام امرأة أوريا الحثي؟».","11:4":"فأرسل داود رسلا وأخذها, فدخلت إليه, فاضطجع معها وهي مطهرة من طمثها. ثم رجعت إلى بيتها.","11:5":"وحبلت المرأة, فأرسلت وأخبرت داود وقالت: «إني حبلى».","11:6":"فأرسل داود إلى يوآب يقول: «أرسل إلي أوريا الحثي». فأرسل يوآب أوريا إلى داود.","11:7":"فأتى أوريا إليه, فسأل داود عن سلامة يوآب وسلامة الشعب ونجاح الحرب.","11:8":"وقال داود لأوريا: «انزل إلى بيتك واغسل رجليك». فخرج أوريا من بيت الملك, وخرجت وراءه حصة من عند الملك.","11:9":"ونام أوريا على باب بيت الملك مع جميع عبيد سيده, ولم ينزل إلى بيته.","11:10":"فأخبروا داود قائلين: «لم ينزل أوريا إلى بيته». فقال داود لأوريا: «أما جئت من السفر؟ فلماذا لم تنزل إلى بيتك؟»","11:11":"فقال أوريا لداود: «إن التابوت وإسرائيل ويهوذا ساكنون في الخيام, وسيدي يوآب وعبيد سيدي نازلون على وجه الصحراء, وأنا آتي إلى بيتي لآكل وأشرب وأضطجع مع امرأتي؟ وحياتك وحياة نفسك, لا أفعل هذا الأمر».","11:12":"فقال داود لأوريا: «أقم هنا اليوم أيضا, وغدا أطلقك». فأقام أوريا في أورشليم ذلك اليوم وغده.","11:13":"ودعاه داود فأكل أمامه وشرب وأسكره. وخرج عند المساء ليضطجع في مضجعه مع عبيد سيده, وإلى بيته لم ينزل.","11:14":"وفي الصباح كتب داود مكتوبا إلى يوآب وأرسله بيد أوريا.","11:15":"وكتب في المكتوب يقول: «اجعلوا أوريا في وجه الحرب الشديدة, وارجعوا من ورائه فيضرب ويموت».","11:16":"وكان في محاصرة يوآب المدينة أنه جعل أوريا في الموضع الذي علم أن رجال البأس فيه.","11:17":"فخرج رجال المدينة وحاربوا يوآب, فسقط بعض الشعب من عبيد داود, ومات أوريا الحثي أيضا.","11:18":"فأرسل يوآب وأخبر داود بجميع أمور الحرب.","11:19":"وأوصى الرسول قائلا: «عندما تفرغ من الكلام مع الملك عن جميع أمور الحرب,","11:20":"فإن اشتعل غضب الملك, وقال لك: لماذا دنوتم من المدينة للقتال؟ أما علمتم أنهم يرمون من على السور؟","11:21":"من قتل أبيمالك بن يربوشث؟ ألم ترمه امرأة بقطعة رحى من على السور فمات في تاباص؟ لماذا دنوتم من السور؟ فقل: قد مات عبدك أوريا الحثي أيضا».","11:22":"فذهب الرسول ودخل وأخبر داود بكل ما أرسله فيه يوآب.","11:23":"وقال الرسول لداود: «قد تجبر علينا القوم وخرجوا إلينا إلى الحقل فكنا عليهم إلى مدخل الباب.","11:24":"فرمى الرماة عبيدك من على السور, فمات البعض من عبيد الملك, ومات عبدك أوريا الحثي أيضا».","11:25":"فقال داود للرسول: « هكذا تقول ليوآب: لا يسؤ في عينيك هذا الأمر, لأن السيف يأكل هذا وذاك. شدد قتالك على المدينة وأخربها. وشدده».","11:26":"فلما سمعت امرأة أوريا أنه قد مات أوريا رجلها, ندبت بعلها.","11:27":"ولما مضت المناحة أرسل داود وضمها إلى بيته, وصارت له امرأة وولدت له ابنا. وأما الأمر الذي فعله داود فقبح في عيني الرب.","12:1":"فأرسل الرب ناثان إلى داود. فجاء إليه وقال له: «كان رجلان في مدينة واحدة, واحد منهما غني والآخر فقير.","12:2":"وكان للغني غنم وبقر كثيرة جدا.","12:3":"وأما الفقير فلم يكن له شيء إلا نعجة واحدة صغيرة قد اقتناها ورباها وكبرت معه ومع بنيه جميعا. تأكل من لقمته وتشرب من كأسه وتنام في حضنه, وكانت له كابنة.","12:4":"فجاء ضيف إلى الرجل الغني, فعفا أن يأخذ من غنمه ومن بقره ليهيئ للضيف الذي جاء إليه, فأخذ نعجة الرجل الفقير وهيأ للرجل الذي جاء إليه».","12:5":"فحمي غضب داود على الرجل جدا, وقال لناثان: «حي هو الرب, إنه يقتل الرجل الفاعل ذلك,","12:6":"ويرد النعجة أربعة أضعاف لأنه فعل هذا الأمر ولأنه لم يشفق».","12:7":"فقال ناثان لداود: «أنت هو الرجل! هكذا قال الرب إله إسرائيل: أنا مسحتك ملكا على إسرائيل وأنقذتك من يد شاول,","12:8":"وأعطيتك بيت سيدك ونساء سيدك في حضنك, وأعطيتك بيت إسرائيل ويهوذا. وإن كان ذلك قليلا, كنت أزيد لك كذا وكذا.","12:9":"لماذا احتقرت كلام الرب لتعمل الشر في عينيه؟ قد قتلت أوريا الحثي بالسيف, وأخذت امرأته لك امرأة, وإياه قتلت بسيف بني عمون.","12:10":"والآن لا يفارق السيف بيتك إلى الأبد, لأنك احتقرتني وأخذت امرأة أوريا الحثي لتكون لك امرأة.","12:11":"هكذا قال الرب: هأنذا أقيم عليك الشر من بيتك, وآخذ نساءك أمام عينيك وأعطيهن لقريبك, فيضطجع مع نسائك في عين هذه الشمس.","12:12":"لأنك أنت فعلت بالسر وأنا أفعل هذا الأمر قدام جميع إسرائيل وقدام الشمس».","12:13":"فقال داود لناثان: «قد أخطأت إلى الرب». فقال ناثان لداود: «الرب أيضا قد نقل عنك خطيتك. لا تموت.","12:14":"غير أنه من أجل أنك قد جعلت بهذا الأمر أعداء الرب يشمتون, فالابن المولود لك يموت».","12:15":"وذهب ناثان إلى بيته. وضرب الرب الولد الذي ولدته امرأة أوريا لداود فثقل.","12:16":"فسأل داود الله من أجل الصبي, وصام داود صوما, ودخل وبات مضطجعا على الأرض.","12:17":"فقام شيوخ بيته عليه ليقيموه عن الأرض فلم يشأ, ولم يأكل معهم خبزا.","12:18":"وكان في اليوم السابع أن الولد مات, فخاف عبيد داود أن يخبروه بأن الولد قد مات لأنهم قالوا: «هوذا لما كان الولد حيا كلمناه فلم يسمع لصوتنا. فكيف نقول له: قد مات الولد؟ يعمل أشر!».","12:19":"ورأى داود عبيده يتناجون, ففطن داود أن الولد قد مات. فقال داود لعبيده: «هل مات الولد؟» فقالوا: «مات».","12:20":"فقام داود عن الأرض واغتسل وادهن وبدل ثيابه ودخل بيت الرب وسجد, ثم جاء إلى بيته وطلب فوضعوا له خبزا فأكل.","12:21":"فقال له عبيده: «ما هذا الأمر الذي فعلت؟ لما كان الولد حيا صمت وبكيت, ولما مات الولد قمت وأكلت خبزا».","12:22":"فقال: «لما كان الولد حيا صمت وبكيت لأني قلت: من يعلم؟ ربما يرحمني الرب ويحيا الولد.","12:23":"والآن قد مات, فلماذا أصوم؟ هل أقدر أن أرده بعد؟ أنا ذاهب إليه وأما هو فلا يرجع إلي».","12:24":"وعزى داود بثشبع امرأته, ودخل إليها واضطجع معها فولدت ابنا, فدعا اسمه سليمان, والرب أحبه,","12:25":"وأرسل بيد ناثان النبي ودعا اسمه «يديديا» من أجل الرب.","12:26":"وحارب يوآب ربة بني عمون وأخذ مدينة المملكة.","12:27":"وأرسل يوآب رسلا إلى داود يقول: «قد حاربت ربة وأخذت أيضا مدينة المياه.","12:28":"فالآن اجمع بقية الشعب وانزل على المدينة وخذها لئلا آخذ أنا المدينة فيدعى باسمي عليها».","12:29":"فجمع داود كل الشعب وذهب إلى ربة وحاربها وأخذها.","12:30":"وأخذ تاج ملكهم عن رأسه, ووزنه وزنة من الذهب مع حجر كريم, وكان على رأس داود. وأخرج غنيمة المدينة كثيرة جدا.","12:31":"وأخرج الشعب الذي فيها ووضعهم تحت مناشير ونوارج حديد وفؤوس حديد وأمرهم في أتون الآجر, وهكذا صنع بجميع مدن بني عمون. ثم رجع داود وجميع الشعب إلى أورشليم.","13:1":"وجرى بعد ذلك أنه كان لأبشالوم بن داود أخت جميلة اسمها ثامار, فأحبها أمنون بن داود.","13:2":"وأحصر أمنون للسقم من أجل ثامار أخته لأنها كانت عذراء, وعسر في عيني أمنون أن يفعل لها شيئا.","13:3":"وكان لأمنون صاحب اسمه يوناداب بن شمعى أخي داود. وكان يوناداب رجلا حكيما جدا.","13:4":"فقال له: «لماذا يا ابن الملك أنت ضعيف هكذا من صباح إلى صباح؟ أما تخبرني؟» فقال له أمنون: «إني أحب ثامار أخت أبشالوم أخي».","13:5":"فقال يوناداب: «اضطجع على سريرك وتمارض. وإذا جاء أبوك ليراك فقل له: دع ثامار أختي فتأتي وتطعمني خبزا, وتعمل أمامي الطعام لأرى فآكل من يدها».","13:6":"فاضطجع أمنون وتمارض, فجاء الملك ليراه. فقال أمنون للملك: «دع ثامار أختي فتأتي وتصنع أمامي كعكتين فآكل من يدها».","13:7":"فأرسل داود إلى ثامار إلى البيت قائلا: «اذهبي إلى بيت أمنون أخيك واعملي له طعاما».","13:8":"فذهبت ثامار إلى بيت أمنون أخيها وهو مضطجع. وأخذت العجين وعجنت وعملت كعكا أمامه وخبزت الكعك,","13:9":"وأخذت المقلاة وسكبت أمامه, فأبى أن يأكل. وقال أمنون: «أخرجوا كل إنسان عني». فخرج كل إنسان عنه.","13:10":"ثم قال أمنون لثامار: «ايتي بالطعام إلى المخدع فآكل من يدك». فأخذت ثامار الكعك الذي عملته وأتت به أمنون أخاها إلى المخدع.","13:11":"وقدمت له ليأكل, فأمسكها وقال لها: «تعالي اضطجعي معي يا أختي».","13:12":"فقالت له: «لا يا أخي, لا تذلني لأنه لا يفعل هكذا في إسرائيل. لا تعمل هذه القباحة.","13:13":"أما أنا فأين أذهب بعاري؟ وأما أنت فتكون كواحد من السفهاء في إسرائيل! والآن كلم الملك لأنه لا يمنعني منك».","13:14":"فلم يشأ أن يسمع لصوتها, بل تمكن منها وقهرها واضطجع معها.","13:15":"ثم أبغضها أمنون بغضة شديدة جدا, حتى إن البغضة التي أبغضها إياها كانت أشد من المحبة التي أحبها إياها. وقال لها أمنون: «قومي انطلقي».","13:16":"فقالت له: «لا سبب! هذا الشر بطردك إياي هو أعظم من الآخر الذي عملته بي». فلم يشأ أن يسمع لها,","13:17":"بل دعا غلامه الذي كان يخدمه وقال: «اطرد هذه عني خارجا وأقفل الباب وراءها».","13:18":"وكان عليها ثوب ملون, لأن بنات الملك العذارى كن يلبسن جبات مثل هذه. فأخرجها خادمه إلى الخارج وأقفل الباب وراءها.","13:19":"فجعلت ثامار رمادا على رأسها, ومزقت الثوب الملون الذي عليها, ووضعت يدها على رأسها وكانت تذهب صارخة.","13:20":"فقال لها أبشالوم أخوها: «هل كان أمنون أخوك معك؟ فالآن يا أختي اسكتي. أخوك هو. لا تضعي قلبك على هذا الأمر». فأقامت ثامار مستوحشة في بيت أبشالوم أخيها.","13:21":"ولما سمع الملك داود بجميع هذه الأمور اغتاظ جدا.","13:22":"ولم يكلم أبشالوم أمنون بشر ولا بخير, لأن أبشالوم أبغض أمنون من أجل أنه أذل ثامار أخته.","13:23":"وكان بعد سنتين من الزمان, أنه كان لأبشالوم جزازون في بعل حاصور التي عند أفرايم. فدعا أبشالوم جميع بني الملك.","13:24":"وجاء أبشالوم إلى الملك وقال: «هوذا لعبدك جزازون. فليذهب الملك وعبيده مع عبدك».","13:25":"فقال الملك لأبشالوم: «لا يا ابني. لا نذهب كلنا لئلا نثقل عليك». فألح عليه, فلم يشأ أن يذهب بل باركه.","13:26":"فقال أبشالوم: «إذا دع أخي أمنون يذهب معنا». فقال الملك: «لماذا يذهب معك؟»","13:27":"فألح عليه أبشالوم, فأرسل معه أمنون وجميع بني الملك.","13:28":"فأوصى أبشالوم غلمانه قائلا: «انظروا. متى طاب قلب أمنون بالخمر وقلت لكم اضربوا أمنون فاقتلوه. لا تخافوا. أليس أني أنا أمرتكم؟ فتشددوا وكونوا ذوي بأس».","13:29":"ففعل غلمان أبشالوم بأمنون كما أمر أبشالوم. فقام جميع بني الملك وركبوا كل واحد على بغله وهربوا.","13:30":"وفيما هم في الطريق وصل الخبر إلى داود وقيل له: «قد قتل أبشالوم جميع بني الملك, ولم يتبق منهم أحد».","13:31":"فقام الملك ومزق ثيابه واضطجع على الأرض وجميع عبيده واقفون وثيابهم ممزقة.","13:32":"فأجاب يوناداب بن شمعى أخي داود وقال: «لا يظن سيدي أنهم قتلوا جميع الفتيان بني الملك. إنما أمنون وحده مات, لأن ذلك قد وضع عند أبشالوم منذ يوم أذل ثامار أخته.","13:33":"والآن لا يضعن سيدي الملك في قلبه شيئا قائلا: إن جميع بني الملك قد ماتوا. إنما أمنون وحده مات».","13:34":"وهرب أبشالوم. ورفع الغلام الرقيب طرفه ونظر وإذا بشعب كثير يسيرون على الطريق وراءه بجانب الجبل.","13:35":"فقال يوناداب للملك: «هوذا بنو الملك قد جاءوا. كما قال عبدك كذلك صار».","13:36":"ولما فرغ من الكلام إذا ببني الملك قد جاءوا ورفعوا أصواتهم وبكوا, وكذلك بكى الملك وعبيده بكاء عظيما جدا.","13:37":"فهرب أبشالوم وذهب إلى تلماي بن عميهود ملك جشور. وناح داود على ابنه الأيام كلها.","13:38":"وهرب أبشالوم وذهب إلى جشور, وكان هناك ثلاث سنين.","13:39":"وكان داود يتوق إلى الخروج إلى أبشالوم, لأنه تعزى عن أمنون حيث إنه مات.","14:1":"وعلم يوآب ابن صروية أن قلب الملك على أبشالوم,","14:2":"فأرسل يوآب إلى تقوع وأخذ من هناك امرأة حكيمة وقال لها: «تظاهري بالحزن, والبسي ثياب الحزن, ولا تدهني بزيت, بل كوني كامرأة لها أيام كثيرة وهي تنوح على ميت.","14:3":"وادخلي إلى الملك وكلميه بهذا الكلام». وجعل يوآب الكلام في فمها.","14:4":"وكلمت المرأة التقوعية الملك, وخرت على وجهها إلى الأرض وسجدت وقالت: «أعن أيها الملك».","14:5":"فقال لها الملك: «ما بالك؟» فقالت: «إني امرأة أرملة. قد مات رجلي.","14:6":"ولجاريتك ابنان, فتخاصما في الحقل وليس من يفصل بينهما, فضرب أحدهما الآخر وقتله.","14:7":"وهوذا العشيرة كلها قد قامت على جاريتك وقالوا: سلمي ضارب أخيه لنقتله بنفس أخيه الذي قتله, فنهلك الوارث أيضا. فيطفئون جمرتي التي بقيت, ولا يتركون لرجلي اسما ولا بقية على وجه الأرض».","14:8":"فقال الملك للمرأة: «اذهبي إلى بيتك وأنا أوصي فيك».","14:9":"فقالت المرأة التقوعية للملك: «علي الإثم يا سيدي الملك وعلى بيت أبي, والملك وكرسيه نقيان».","14:10":"فقال الملك: «إذا كلمك أحد فأتي به إلي فلا يعود يمسك بعد».","14:11":"فقالت: «اذكر أيها الملك الرب إلهك حتى لا يكثر ولي الدم القتل, لئلا يهلكوا ابني». فقال: «حي هو الرب, إنه لا تسقط شعرة من شعر ابنك إلى الأرض».","14:12":"فقالت المرأة: «لتتكلم جاريتك كلمة إلى سيدي الملك». فقال: «تكلمي»","14:13":"فقالت المرأة: «ولماذا افتكرت بمثل هذا الأمر على شعب الله؟ ويتكلم الملك بهذا الكلام كمذنب بما أن الملك لا يرد منفيه.","14:14":"لأنه لا بد أن نموت ونكون كالماء المهراق على الأرض الذي لا يجمع أيضا. ولا ينزع الله نفسا بل يفكر أفكارا حتى لا يطرد عنه منفيه.","14:15":"والآن حيث إني جئت لأكلم الملك سيدي بهذا الأمر, لأن الشعب أخافني, فقالت جاريتك: أكلم الملك لعل الملك يفعل كقول أمته.","14:16":"لأن الملك يسمع لينقذ أمته من يد الرجل الذي يريد أن يهلكني أنا وابني معا من نصيب الله.","14:17":"فقالت جاريتك: ليكن كلام سيدي الملك عزاء, لأنه سيدي الملك إنما هو كملاك الله لفهم الخير والشر, والرب إلهك يكون معك».","14:18":"فأجاب الملك وقال للمرأة: «لا تكتمي عني أمرا أسألك عنه». فقالت المرأة: «ليتكلم سيدي الملك».","14:19":"فقال الملك: «هل يد يوآب معك في هذا كله؟» فأجابت المرأة وقالت: «حية هي نفسك يا سيدي الملك, لا يحاد يمينا أو يسارا عن كل ما تكلم به سيدي الملك, لأن عبدك يوآب هو أوصاني, وهو وضع في فم جاريتك كل هذا الكلام.","14:20":"لأجل تحويل وجه الكلام فعل عبدك يوآب هذا الأمر, وسيدي حكيم كحكمة ملاك الله ليعلم كل ما في الأرض».","14:21":"فقال الملك ليوآب: «هأنذا قد فعلت هذا الأمر, فاذهب رد الفتى أبشالوم».","14:22":"فسقط يوآب على وجهه إلى الأرض وسجد وبارك الملك, وقال يوآب: «اليوم علم عبدك أني قد وجدت نعمة في عينيك يا سيدي الملك, إذ فعل الملك قول عبده».","14:23":"ثم قام يوآب وذهب إلى جشور وأتى بأبشالوم إلى أورشليم.","14:24":"فقال الملك: «لينصرف إلى بيته ولا ير وجهي». فانصرف أبشالوم إلى بيته ولم ير وجه الملك.","14:25":"ولم يكن في كل إسرائيل رجل جميل وممدوح جدا كأبشالوم, من باطن قدمه حتى هامته لم يكن فيه عيب.","14:26":"وعند حلقه رأسه, إذ كان يحلقه في آخر كل سنة, لأنه كان يثقل عليه فيحلقه, كان يزن شعر رأسه مئتي شاقل بوزن الملك.","14:27":"وولد لأبشالوم ثلاثة بنين وبنت واحدة اسمها ثامار, وكانت امرأة جميلة المنظر.","14:28":"وأقام أبشالوم في أورشليم سنتين ولم ير وجه الملك.","14:29":"فأرسل أبشالوم إلى يوآب ليرسله إلى الملك, فلم يشأ أن يأتي إليه. ثم أرسل أيضا ثانية, فلم يشأ أن يأتي.","14:30":"فقال لعبيده: «انظروا. حقلة يوآب بجانبي, وله هناك شعير. اذهبوا وأحرقوه بالنار». فأحرق عبيد أبشالوم الحقلة بالنار.","14:31":"فقام يوآب وجاء إلى أبشالوم إلى البيت وقال له: «لماذا أحرق عبيدك حقلتي بالنار؟»","14:32":"فقال أبشالوم ليوآب: «هأنذا قد أرسلت إليك قائلا: تعال إلى هنا فأرسلك إلى الملك تقول: لماذا جئت من جشور؟ خير لي لو كنت باقيا هناك. فالآن إني أرى وجه الملك, وإن وجد في إثم فليقتلني».","14:33":"فجاء يوآب إلى الملك وأخبره. ودعا أبشالوم, فأتى إلى الملك وسجد على وجهه إلى الأرض قدام الملك, فقبل الملك أبشالوم.","15:1":"وكان بعد ذلك أن أبشالوم اتخذ مركبة وخيلا وخمسين رجلا يجرون قدامه.","15:2":"وكان أبشالوم يبكر ويقف بجانب طريق الباب, وكل صاحب دعوى آت إلى الملك لأجل الحكم, كان أبشالوم يدعوه إليه ويقول: «من أية مدينة أنت؟» فيقول: «من أحد أسباط إسرائيل عبدك».","15:3":"فيقول أبشالوم له: «انظر. أمورك صالحة ومستقيمة, ولكن ليس من يسمع لك من قبل الملك».","15:4":"ثم يقول أبشالوم: «من يجعلني قاضيا في الأرض فيأتي إلي كل إنسان له خصومة ودعوى فأنصفه؟».","15:5":"وكان إذا تقدم أحد ليسجد له, يمد يده ويمسكه ويقبله.","15:6":"وكان أبشالوم يفعل مثل هذا الأمر لجميع إسرائيل الذين كانوا يأتون لأجل الحكم إلى الملك, فاسترق أبشالوم قلوب رجال إسرائيل.","15:7":"وفي نهاية أربعين سنة قال أبشالوم للملك: «دعني فأذهب وأوفي نذري الذي نذرته للرب في حبرون,","15:8":"لأن عبدك نذر نذرا عند سكناي في جشور في أرام قائلا: إن أرجعني الرب إلى أورشليم فإني أعبد الرب».","15:9":"فقال له الملك: «اذهب بسلام». فقام وذهب إلى حبرون.","15:10":"وأرسل أبشالوم جواسيس في جميع أسباط إسرائيل قائلا: «إذا سمعتم صوت البوق, فقولوا: قد ملك أبشالوم في حبرون».","15:11":"وانطلق مع أبشالوم مئتا رجل من أورشليم قد دعوا وذهبوا ببساطة, ولم يكونوا يعلمون شيئا.","15:12":"وأرسل أبشالوم إلى أخيتوفل الجيلوني مشير داود من مدينته جيلوه إذ كان يذبح ذبائح. وكانت الفتنة شديدة وكان الشعب لا يزال يتزايد مع أبشالوم.","15:13":"فأتى مخبر إلى داود قائلا: «إن قلوب رجال إسرائيل صارت وراء أبشالوم».","15:14":"فقال داود لجميع عبيده الذين معه في أورشليم: «قوموا بنا نهرب, لأنه ليس لنا نجاة من وجه أبشالوم. أسرعوا للذهاب لئلا يبادر ويدركنا وينزل بنا الشر ويضرب المدينة بحد السيف».","15:15":"فقال عبيد الملك للملك: «حسب كل ما يختاره سيدنا الملك نحن عبيده».","15:16":"فخرج الملك وجميع بيته وراءه. وترك الملك عشر نساء سراري لحفظ البيت.","15:17":"وخرج الملك وكل الشعب في أثره ووقفوا عند البيت الأبعد.","15:18":"وجميع عبيده كانوا يعبرون بين يديه مع جميع الجلادين والسعاة وجميع الجتيين, ست مئة رجل أتوا وراءه من جت, وكانوا يعبرون بين يدي الملك.","15:19":"فقال الملك لإتاي الجتي: «لماذا تذهب أنت أيضا معنا؟ ارجع وأقم مع الملك لأنك غريب ومنفي أيضا من وطنك.","15:20":"أمسا جئت واليوم أتيهك بالذهاب معنا وأنا أنطلق إلى حيث أنطلق؟ ارجع ورجع إخوتك. الرحمة والحق معك».","15:21":"فأجاب إتاي الملك وقال: «حي هو الرب وحي سيدي الملك, إنه حيثما كان سيدي الملك, إن كان للموت أو للحياة, فهناك يكون عبدك أيضا».","15:22":"فقال داود لإتاي: «اذهب واعبر». فعبر إتاي الجتي وجميع رجاله وجميع الأطفال الذين معه.","15:23":"وكانت جميع الأرض تبكي بصوت عظيم, وجميع الشعب يعبرون. وعبر الملك في وادي قدرون, وعبر جميع الشعب نحو طريق البرية.","15:24":"وإذا بصادوق أيضا وجميع اللاويين معه يحملون تابوت عهد الله. فوضعوا تابوت الله, وصعد أبياثار حتى انتهى جميع الشعب من العبور من المدينة.","15:25":"فقال الملك لصادوق: «أرجع تابوت الله إلى المدينة, فإن وجدت نعمة في عيني الرب فإنه يرجعني ويريني إياه ومسكنه.","15:26":"وإن قال هكذا: إني لم أسر بك. فهأنذا, فليفعل بي حسبما يحسن في عينيه».","15:27":"ثم قال الملك لصادوق الكاهن: «أأنت راء؟ فارجع إلى المدينة بسلام أنت وأخيمعص ابنك ويوناثان بن أبياثار. ابناكما كلاهما معكما.","15:28":"انظروا. أني أتوانى في سهول البرية حتى تأتي كلمة منكم لتخبيري».","15:29":"فأرجع صادوق وأبياثار تابوت الله إلى أورشليم وأقاما هناك.","15:30":"وأما داود فصعد في مصعد جبل الزيتون. كان يصعد باكيا ورأسه مغطى ويمشي حافيا, وجميع الشعب الذين معه غطوا كل واحد رأسه, وكانوا يصعدون وهم يبكون.","15:31":"وأخبر داود وقيل له: «إن أخيتوفل بين الفاتنين مع أبشالوم» فقال داود: «حمق يا رب مشورة أخيتوفل».","15:32":"ولما وصل داود إلى القمة حيث سجد لله, إذا بحوشاي الأركي قد لقيه ممزق الثوب والتراب على رأسه.","15:33":"فقال له داود: «إذا عبرت معي تكون علي حملا.","15:34":"ولكن إذا رجعت إلى المدينة وقلت لأبشالوم: أنا أكون عبدك أيها الملك. أنا عبد أبيك منذ زمان والآن أنا عبدك. فإنك تبطل لي مشورة أخيتوفل.","15:35":"أليس معك هناك صادوق وأبياثار الكاهنان. فكل ما تسمعه من بيت الملك, فأخبر به صادوق وأبياثار الكاهنين.","15:36":"هوذا هناك معهما ابناهما أخيمعص لصادوق ويوناثان لأبياثار. فترسلون على أيديهما إلي كل كلمة تسمعونها».","15:37":"فأتى حوشاي صاحب داود إلى المدينة, وأبشالوم يدخل أورشليم.","16:1":"ولما عبر داود قليلا عن القمة, إذا بصيبا غلام مفيبوشث قد لقيه بحمارين مشدودين, عليهما مئتا رغيف خبز ومئة عنقود زبيب ومئة قرص تين وزق خمر.","16:2":"فقال الملك لصيبا: «ما لك وهذه؟» فقال صيبا: «الحماران لبيت الملك للركوب, والخبز والتين للغلمان ليأكلوا, والخمر ليشربه من أعيا في البرية».","16:3":"فقال الملك: «وأين ابن سيدك؟» فقال صيبا للملك: «هوذا هو مقيم في أورشليم, لأنه قال: اليوم يرد لي بيت إسرائيل مملكة أبي».","16:4":"فقال الملك لصيبا: «هوذا لك كل ما لمفيبوشث». فقال صيبا: «سجدت! ليتني أجد نعمة في عينيك يا سيدي الملك».","16:5":"ولما جاء الملك داود إلى بحوريم إذا برجل خارج من هناك من عشيرة بيت شاول, اسمه شمعي بن جيرا, يسب وهو يخرج,","16:6":"ويرشق بالحجارة داود وجميع عبيد الملك داود وجميع الشعب وجميع الجبابرة عن يمينه وعن يساره.","16:7":"وهكذا كان شمعي يقول في سبه: «اخرج! اخرج يا رجل الدماء ورجل بليعال!","16:8":"قد رد الرب عليك كل دماء بيت شاول الذي ملكت عوضا عنه, وقد دفع الرب المملكة ليد أبشالوم ابنك, وها أنت واقع بشرك لأنك رجل دماء».","16:9":"فقال أبيشاي ابن صروية؟ للملك: «لماذا يسب هذا الكلب الميت سيدي الملك؟ دعني أعبر فأقطع رأسه».","16:10":"فقال الملك: «ما لي ولكم يا بني صروية! دعوه يسب لأن الرب قال له: سب داود. ومن يقول: لماذا تفعل هكذا؟»","16:11":"وقال داود لأبيشاي ولجميع عبيده: «هوذا ابني الذي خرج من أحشائي يطلب نفسي, فكم بالحري الآن بنياميني؟ دعوه يسب لأن الرب قال له.","16:12":"لعل الرب ينظر إلى مذلتي ويكافئني الرب خيرا عوض مسبته بهذا اليوم».","16:13":"وإذ كان داود ورجاله يسيرون في الطريق, كان شمعي يسير في جانب الجبل مقابله ويسب وهو سائر ويرشق بالحجارة مقابله ويذري التراب.","16:14":"وجاء الملك وكل الشعب الذين معه وقد أعيوا فاستراحوا هناك.","16:15":"وأما أبشالوم وجميع الشعب رجال إسرائيل, فأتوا إلى أورشليم وأخيتوفل معهم.","16:16":"ولما جاء حوشاي الأركي صاحب داود إلى أبشالوم, قال حوشاي لأبشالوم: «ليحي الملك! ليحي الملك!»","16:17":"فقال أبشالوم لحوشاي: «أهذا معروفك مع صاحبك؟ لماذا لم تذهب مع صاحبك؟»","16:18":"فقال حوشاي لأبشالوم: «كلا, ولكن الذي اختاره الرب وهذا الشعب وكل رجال إسرائيل فله أكون ومعه أقيم.","16:19":"وثانيا: من أخدم؟ أليس بين يدي ابنه؟ كما خدمت بين يدي أبيك كذلك أكون بين يديك».","16:20":"وقال أبشالوم لأخيتوفل: «أعطوا مشورة, ماذا نفعل؟».","16:21":"فقال أخيتوفل لأبشالوم: «ادخل إلى سراري أبيك اللواتي تركهن لحفظ البيت, فيسمع كل إسرائيل أنك قد صرت مكروها من أبيك, فتتشدد أيدي جميع الذين معك».","16:22":"فنصبوا لأبشالوم الخيمة على السطح, ودخل أبشالوم إلى سراري أبيه أمام جميع إسرائيل.","16:23":"وكانت مشورة أخيتوفل التي كان يشير بها في تلك الأيام كمن يسأل بكلام الله. هكذا كل مشورة أخيتوفل على داود وعلى أبشالوم جميعا.","17:1":"وقال أخيتوفل لأبشالوم: «دعني أنتخب اثني عشر ألف رجل وأقوم وأسعى وراء داود هذه الليلة,","17:2":"فآتي عليه وهو متعب ومرتخي اليدين فأزعجه, فيهرب كل الشعب الذي معه, وأضرب الملك وحده.","17:3":"وأرد جميع الشعب إليك. كرجوع الجميع هو الرجل الذي تطلبه, فيكون كل الشعب في سلام».","17:4":"فحسن الأمر في عيني أبشالوم وأعين جميع شيوخ إسرائيل.","17:5":"فقال أبشالوم: «ادع أيضا حوشاي الأركي فنسمع ما يقول هو أيضا».","17:6":"فلما جاء حوشاي إلى أبشالوم, كلمه أبشالوم قائلا: «بمثل هذا الكلام تكلم أخيتوفل. أنعمل حسب كلامه أم لا؟ تكلم أنت».","17:7":"فقال حوشاي لأبشالوم: «ليست حسنة المشورة التي أشار بها أخيتوفل هذه المرة».","17:8":"ثم قال حوشاي: «أنت تعلم أباك ورجاله أنهم جبابرة, وأن أنفسهم مرة كدبة مثكل في الحقل. وأبوك رجل قتال ولا يبيت مع الشعب.","17:9":"ها هو الآن مختبئ في إحدى الحفر أو أحد الأماكن. ويكون إذا سقط بعضهم في الابتداء أن السامع يسمع فيقول: قد صارت كسرة في الشعب الذي وراء أبشالوم.","17:10":"أيضا ذو البأس الذي قلبه كقلب الأسد يذوب ذوبانا, لأن جميع إسرائيل يعلمون أن أباك جبار, والذين معه ذوو بأس.","17:11":"لذلك أشير بأن يجتمع إليك كل إسرائيل من دان إلى بئر سبع, كالرمل الذي على البحر في الكثرة, وحضرتك سائر في الوسط.","17:12":"ونأتي إليه إلى أحد الأماكن حيث هو, وننزل عليه نزول الطل على الأرض, ولا يبقى منه ولا من جميع الرجال الذين معه واحد.","17:13":"وإذا انحاز إلى مدينة, يحمل جميع إسرائيل إلى تلك المدينة حبالا, فنجرها إلى الوادي حتى لا تبقى هناك ولا حصاة».","17:14":"فقال أبشالوم وكل رجال إسرائيل: «إن مشورة حوشاي الأركي أحسن من مشورة أخيتوفل». فإن الرب أمر بإبطال مشورة أخيتوفل الصالحة, لكي ينزل الرب الشر بأبشالوم.","17:15":"وقال حوشاي لصادوق وأبياثار الكاهنين: «كذا وكذا أشار أخيتوفل على أبشالوم وعلى شيوخ إسرائيل, وكذا وكذا أشرت أنا.","17:16":"فالآن أرسلوا عاجلا وأخبروا داود قائلين: لا تبت هذه الليلة في سهول البرية, بل اعبر لئلا يبتلع الملك وجميع الشعب الذي معه».","17:17":"وكان يوناثان وأخيمعص واقفين عند عين روجل, فانطلقت الجارية وأخبرتهما, وهما ذهبا وأخبرا الملك داود, لأنهما لم يقدرا أن يريا داخلين المدينة.","17:18":"فرآهما غلام وأخبر أبشالوم. فذهبا كلاهما عاجلا ودخلا بيت رجل في بحوريم وله بئر في داره, فنزلا إليها.","17:19":"فأخذت المرأة وفرشت سجفا على فم البئر وسطحت عليه سميذا فلم يعلم الأمر.","17:20":"فجاء عبيد أبشالوم إلى المرأة إلى البيت وقالوا: «أين أخيمعص ويوناثان؟» فقالت لهم المرأة: «قد عبرا قناة الماء». ولما فتشوا ولم يجدوهما رجعوا إلى أورشليم.","17:21":"وبعد ذهابهم خرجا من البئر وذهبا وأخبرا الملك داود, وقالا لداود: «قوموا واعبروا سريعا الماء, لأن هكذا أشار عليكم أخيتوفل».","17:22":"فقام داود وجميع الشعب الذي معه وعبروا الأردن. وعند ضوء الصباح لم يبق أحد لم يعبر الأردن.","17:23":"وأما أخيتوفل فلما رأى أن مشورته لم يعمل بها, شد على الحمار وقام وانطلق إلى بيته إلى مدينته, وأوصى لبيته, وخنق نفسه ومات ودفن في قبر أبيه.","17:24":"وجاء داود إلى محنايم. وعبر أبشالوم الأردن هو وجميع رجال إسرائيل معه.","17:25":"وأقام أبشالوم عماسا بدل يوآب على الجيش. وكان عماسا ابن رجل اسمه يثرا الإسرائيلي الذي دخل إلى أبيجايل بنت ناحاش أخت صروية أم يوآب.","17:26":"ونزل إسرائيل وأبشالوم في أرض جلعاد.","17:27":"وكان لما جاء داود إلى محنايم أن شوبي بن ناحاش من ربة بني عمون, وماكير بن عميئيل من لودبار, وبرزلاي الجلعادي من روجليم,","17:28":"قدموا فرشا وطسوسا وآنية خزف وحنطة وشعيرا ودقيقا وفريكا وفولا وعدسا وحمصا مشويا","17:29":"وعسلا وزبدة وضأنا وجبن بقر, لداود وللشعب الذي معه ليأكلوا, لأنهم قالوا: «الشعب جوعان ومتعب وعطشان في البرية».","18:1":"وأحصى داود الشعب الذي معه, وجعل عليهم رؤساء ألوف ورؤساء مئات.","18:2":"وأرسل داود الشعب ثلثا بيد يوآب, وثلثا بيد أبيشاي ابن صروية أخي يوآب, وثلثا بيد إتاي الجتي. وقال الملك للشعب: «إني أنا أيضا أخرج معكم».","18:3":"فقال الشعب: «لا تخرج, لأننا إذا هربنا لا يبالون بنا, وإذا مات نصفنا لا يبالون بنا. والآن أنت كعشرة آلاف منا. والآن الأصلح أن تكون لنا نجدة من المدينة».","18:4":"فقال لهم الملك: «ما يحسن في أعينكم أفعله». فوقف الملك بجانب الباب وخرج جميع الشعب مئات وألوفا.","18:5":"وأوصى الملك يوآب وأبيشاي وإتاي قائلا: «ترفقوا لي بالفتى أبشالوم». وسمع جميع الشعب حين أوصى الملك جميع الرؤساء بأبشالوم.","18:6":"وخرج الشعب إلى الحقل للقاء إسرائيل. وكان القتال في وعر أفرايم,","18:7":"فانكسر هناك شعب إسرائيل أمام عبيد داود, وكانت هناك مقتلة عظيمة في ذلك اليوم. قتل عشرون ألفا.","18:8":"وكان القتال هناك منتشرا على وجه كل الأرض, وزاد الذين أكلهم الوعر من الشعب على الذين أكلهم السيف في ذلك اليوم.","18:9":"وصادف أبشالوم عبيد داود, وكان أبشالوم راكبا على بغل, فدخل البغل تحت أغصان البطمة العظيمة الملتفة, فتعلق رأسه بالبطمة وعلق بين السماء والأرض, والبغل الذي تحته مر.","18:10":"فرآه رجل وأخبر يوآب وقال: «إني قد رأيت أبشالوم معلقا بالبطمة».","18:11":"فقال يوآب للرجل الذي أخبره: «إنك قد رأيته, فلماذا لم تضربه هناك إلى الأرض؟ وعلي أن أعطيك عشرة من الفضة ومنطقة»","18:12":"فقال الرجل ليوآب: «فلو وزن في يدي ألف من الفضة لما كنت أمد يدي إلى ابن الملك, لأن الملك أوصاك في آذاننا أنت وأبيشاي وإتاي قائلا: احترزوا أيا كان منكم على الفتى أبشالوم.","18:13":"وإلا فكنت فعلت بنفسي زورا, إذ لا يخفى عن الملك شيء, وأنت كنت وقفت ضدي».","18:14":"فقال يوآب: «إني لا أصبر هكذا أمامك». فأخذ ثلاثة سهام بيده ونشبها في قلب أبشالوم, وهو بعد حي في قلب البطمة.","18:15":"وأحاط بها عشرة غلمان حاملو سلاح يوآب, وضربوا أبشالوم وأماتوه.","18:16":"وضرب يوآب بالبوق فرجع الشعب عن اتباع إسرائيل, لأن يوآب منع الشعب.","18:17":"وأخذوا أبشالوم وطرحوه في الوعر في الجب العظيم, وأقاموا عليه رجمة عظيمة جدا من الحجارة. وهرب كل إسرائيل, كل واحد إلى خيمته.","18:18":"وكان أبشالوم قد أخذ وأقام لنفسه وهو حي النصب الذي في وادي الملك, لأنه قال: «ليس لي ابن لأجل تذكير اسمي». ودعا النصب باسمه, وهو يدعى «يد أبشالوم» إلى هذا اليوم.","18:19":"وقال أخيمعص بن صادوق: «دعني أجر فأبشر الملك, لأن الله قد انتقم له من أعدائه».","18:20":"فقال له يوآب: «ما أنت صاحب بشارة في هذا اليوم. في يوم آخر تبشر, وهذا اليوم لا تبشر من أجل أن ابن الملك قد مات».","18:21":"وقال يوآب لكوشي: «اذهب وأخبر الملك بما رأيت». فسجد كوشي ليوآب وركض.","18:22":"وعاد أيضا أخيمعص بن صادوق فقال ليوآب: «مهما كان, فدعني أجر أنا أيضا وراء كوشي». فقال يوآب: «لماذا تجري أنت يا ابني, وليس لك بشارة تجازى؟»","18:23":"قال: «مهما كان أجري». فقال له: «اجر». فجرى أخيمعص في طريق الغور وسبق كوشي.","18:24":"وكان داود جالسا بين البابين, وطلع الرقيب إلى سطح الباب إلى السور ورفع عينيه ونظر وإذا برجل يجري وحده.","18:25":"فنادى الرقيب وأخبر الملك. فقال الملك: «إن كان وحده ففي فمه بشارة». وكان يسعى ويقرب.","18:26":"ثم رأى الرقيب رجلا آخر يجري, فنادى الرقيب البواب وقال: «هوذا رجل يجري وحده». فقال الملك: «وهذا أيضا مبشر».","18:27":"وقال الرقيب: «إني أرى جري الأول كجري أخيمعص بن صادوق». فقال الملك: «هذا رجل صالح ويأتي ببشارة صالحة».","18:28":"فنادى أخيمعص وقال للملك: «السلام». وسجد للملك على وجهه إلى الأرض. وقال: «مبارك الرب إلهك الذي دفع القوم الذين رفعوا أيديهم على سيدي الملك».","18:29":"فقال الملك: «أسلام للفتى أبشالوم؟» فقال أخيمعص: «قد رأيت جمهورا عظيما عند إرسال يوآب عبد الملك وعبدك, ولم أعلم ماذا».","18:30":"فقال الملك: «در وقف ههنا». فدار ووقف.","18:31":"وإذا بكوشي قد أتى, وقال كوشي: « ليبشر سيدي الملك, لأن الرب قد انتقم لك اليوم من جميع القائمين عليك».","18:32":"فقال الملك لكوشي: «أسلام للفتى أبشالوم؟» فقال كوشي: «ليكن كالفتى أعداء سيدي الملك وجميع الذين قاموا عليك للشر».","18:33":"فانزعج الملك وصعد إلى علية الباب وكان يبكي ويقول وهو يتمشى: «يا ابني أبشالوم, يا ابني, يا ابني أبشالوم! يا ليتني مت عوضا عنك! يا أبشالوم ابني, يا ابني».","19:1":"فأخبر يوآب: «هوذا الملك يبكي وينوح على أبشالوم».","19:2":"فصارت الغلبة في ذلك اليوم مناحة عند جميع الشعب, لأن الشعب سمعوا في ذلك اليوم من يقول إن الملك قد تأسف على ابنه.","19:3":"وتسلل الشعب في ذلك اليوم للدخول إلى المدينة كما يتسلل القوم الخجلون عندما يهربون في القتال.","19:4":"وستر الملك وجهه وصرخ الملك بصوت عظيم: «يا ابني أبشالوم, يا أبشالوم ابني, يا ابني!».","19:5":"فدخل يوآب إلى الملك إلى البيت وقال: «قد أخزيت اليوم وجوه جميع عبيدك, منقذي نفسك اليوم وأنفس بنيك وبناتك وأنفس نسائك وأنفس سراريك,","19:6":"بمحبتك لمبغضيك وبغضك لمحبيك, لأنك أظهرت اليوم أنه ليس لك رؤساء ولا عبيد, لأني علمت اليوم أنه لو كان أبشالوم حيا وكلنا اليوم موتى, لحسن حينئذ الأمر في عينيك.","19:7":"فالآن قم واخرج وطيب قلوب عبيدك, لأني قد أقسمت بالرب إنه إن لم تخرج لا يبيت أحد معك هذه الليلة, ويكون ذلك أشر عليك من كل شر أصابك منذ صباك إلى الآن».","19:8":"فقام الملك وجلس في الباب. فأخبروا جميع الشعب قائلين: «هوذا الملك جالس في الباب». فأتى جميع الشعب أمام الملك. وأما إسرائيل فهربوا كل واحد إلى خيمته.","19:9":"وكان جميع الشعب في خصام في جميع أسباط إسرائيل قائلين: «إن الملك قد أنقذنا من يد أعدائنا وهو نجانا من يد الفلسطينيين, والآن قد هرب من الأرض لأجل أبشالوم","19:10":"وأبشالوم الذي مسحناه علينا قد مات في الحرب. فالآن لماذا أنتم ساكتون عن إرجاع الملك؟»","19:11":"وأرسل الملك داود إلى صادوق وأبياثار الكاهنين قائلا: «كلما شيوخ يهوذا قائلين: لماذا تكونون آخرين في إرجاع الملك إلى بيته, وقد أتى كلام جميع إسرائيل إلى الملك في بيته؟","19:12":"أنتم إخوتي. أنتم عظمي ولحمي. فلماذا تكونون آخرين في إرجاع الملك؟","19:13":"وتقولان لعماسا: أما أنت عظمي ولحمي؟ هكذا يفعل بي الله وهكذا يزيد, إن كنت لا تصير رئيس جيش عندي كل الأيام بدل يوآب».","19:14":"فاستمال بقلوب جميع رجال يهوذا كرجل واحد, فأرسلوا إلى الملك قائلين: «ارجع أنت وجميع عبيدك».","19:15":"فرجع الملك وأتى إلى الأردن, وأتى يهوذا إلى الجلجال سائرا لملاقاة الملك ليعبر الملك الأردن.","19:16":"فبادر شمعي بن جيرا البنياميني الذي من بحوريم ونزل مع رجال يهوذا للقاء الملك داود,","19:17":"ومعه ألف رجل من بنيامين, وصيبا غلام بيت شاول وبنوه الخمسة عشر وعبيده العشرون معه, فخاضوا الأردن أمام الملك.","19:18":"وعبر القارب لتعبير بيت الملك ولعمل ما يحسن في عينيه. وسقط شمعي بن جيرا أمام الملك عندما عبر الأردن,","19:19":"وقال للملك: «لا يحسب لي سيدي إثما, ولا تذكر ما افترى به عبدك يوم خروج سيدي الملك من أورشليم, حتى يضع الملك ذلك في قلبه,","19:20":"لأن عبدك يعلم أني قد أخطأت, وهأنذا قد جئت اليوم أول كل بيت يوسف, ونزلت للقاء سيدي الملك».","19:21":"فأجاب أبيشاي ابن صروية وقال: «ألا يقتل شمعي لأجل هذا, لأنه سب مسيح الرب؟»","19:22":"فقال داود: «ما لي ولكم يا بني صروية حتى تكونوا لي اليوم مقاومين؟ آليوم يقتل أحد في إسرائيل؟ أفما علمت أني اليوم ملك على إسرائيل؟»","19:23":"ثم قال الملك لشمعي: «لا تموت». وحلف له الملك.","19:24":"ونزل مفيبوشث ابن شاول للقاء الملك, ولم يعتن برجليه, ولا اعتنى بلحيته, ولا غسل ثيابه, من اليوم الذي ذهب فيه الملك إلى اليوم الذي أتى فيه بسلام.","19:25":"فلما جاء إلى أورشليم للقاء الملك, قال له الملك: «لماذا لم تذهب معي يا مفيبوشث؟»","19:26":"فقال: «يا سيدي الملك إن عبدي قد خدعني, لأن عبدك قال: أشد لنفسي الحمار فأركب عليه وأذهب مع الملك, لأن عبدك أعرج.","19:27":"ووشى بعبدك إلى سيدي الملك, وسيدي الملك كملاك الله. فافعل ما يحسن في عينيك.","19:28":"لأن كل بيت أبي لم يكن إلا أناسا موتى لسيدي الملك, وقد جعلت عبدك بين الآكلين على مائدتك. فأي حق لي بعد حتى أصرخ أيضا إلى الملك؟»","19:29":"فقال له الملك: «لماذا تتكلم بعد بأمورك؟ قد قلت إنك أنت وصيبا تقسمان الحقل».","19:30":"فقال مفيبوشث للملك: «فليأخذ الكل أيضا بعد أن جاء سيدي الملك بسلام إلى بيته».","19:31":"ونزل برزلاي الجلعادي من روجليم وعبر الأردن مع الملك ليشيعه عند الأردن.","19:32":"وكان برزلاي قد شاخ جدا. كان ابن ثمانين سنة. وهو عال الملك عند إقامته في محنايم لأنه كان رجلا عظيما جدا.","19:33":"فقال الملك لبرزلاي: «اعبر أنت معي وأنا أعولك معي في أورشليم».","19:34":"فقال برزلاي للملك: «كم أيام سني حياتي حتى أصعد مع الملك إلى أورشليم؟","19:35":"أنا اليوم ابن ثمانين سنة. هل أميز بين الطيب والرديء؟ وهل يستطعم عبدك بما آكل وما أشرب؟ وهل أسمع أيضا أصوات المغنين والمغنيات؟ فلماذا يكون عبدك أيضا ثقلا على سيدي الملك؟","19:36":"يعبر عبدك قليلا الأردن مع الملك. ولماذا يكافئني الملك بهذه المكافأة؟","19:37":"دع عبدك يرجع فأموت في مدينتي عند قبر أبي وأمي. وهوذا عبدك كمهام يعبر مع سيدي الملك, فافعل له ما يحسن في عينيك».","19:38":"فأجاب الملك: «إن كمهام يعبر معي فأفعل له ما يحسن في عينيك, وكل ما تتمناه مني أفعله لك».","19:39":"فعبر جميع الشعب الأردن, والملك عبر. وقبل الملك برزلاي وباركه, فرجع إلى مكانه.","19:40":"وعبر الملك إلى الجلجال, وعبر كمهام معه, وكل شعب يهوذا عبروا الملك, وكذلك نصف شعب إسرائيل.","19:41":"وإذا بجميع رجال إسرائيل جاءون إلى الملك, وقالوا للملك: «لماذا سرقك إخوتنا رجال يهوذا وعبروا الأردن بالملك وبيته وكل رجال داود معه؟».","19:42":"فأجاب كل رجال يهوذا رجال إسرائيل: «لأن الملك قريب إلي, ولماذا تغتاظ من هذا الأمر؟ هل أكلنا شيئا من الملك أو وهبنا هبة؟»","19:43":"فأجاب رجال إسرائيل رجال يهوذا وقالوا: «لي عشرة أسهم في الملك, وأنا أحق منك بداود, فلماذا استخففت بي ولم يكن كلامي أولا في إرجاع ملكي؟» وكان كلام رجال يهوذا أقسى من كلام رجال إسرائيل.","20:1":"واتفق هناك رجل لئيم اسمه شبع بن بكري رجل بنياميني, فضرب بالبوق وقال: «ليس لنا قسم في داود ولا لنا نصيب في ابن يسى. كل رجل إلى خيمته يا إسرائيل».","20:2":"فصعد كل رجال إسرائيل من وراء داود إلى وراء شبع بن بكري. وأما رجال يهوذا فلازموا ملكهم من الأردن إلى أورشليم.","20:3":"وجاء داود إلى بيته في أورشليم. وأخذ الملك النساء السراري العشر اللواتي تركهن لحفظ البيت, وجعلهن تحت حجز, وكان يعولهن ولكن لم يدخل إليهن, بل كن محبوسات إلى يوم موتهن في عيشة العزوبة.","20:4":"وقال الملك لعماسا: «اجمع لي رجال يهوذا في ثلاثة أيام, واحضر أنت هنا».","20:5":"فذهب عماسا ليجمع يهوذا, ولكنه تأخر عن الميقات الذي عينه.","20:6":"فقال داود لأبيشاي: «الآن يسيء إلينا شبع بن بكري أكثر من أبشالوم. فخذ أنت عبيد سيدك واتبعه لئلا يجد لنفسه مدنا حصينة وينفلت من أمام أعيننا».","20:7":"فخرج وراءه رجال يوآب: الجلادون والسعاة وجميع الأبطال, وخرجوا من أورشليم ليتبعوا شبع بن بكري.","20:8":"ولما كانوا عند الصخرة العظيمة التي في جبعون, جاء عماسا قدامهم. وكان يوآب متنطقا على ثوبه الذي كان لابسه, وفوقه منطقة سيف في غمده مشدودة على حقويه, فلما خرج اندلق السيف.","20:9":"فقال يوآب لعماسا: «أسالم أنت يا أخي؟» وأمسكت يد يوآب اليمنى بلحية عماسا ليقبله.","20:10":"وأما عماسا فلم يحترز من السيف الذي بيد يوآب, فضربه به في بطنه فدلق أمعاءه إلى الأرض ولم يثن عليه, فمات. وأما يوآب وأبيشاي أخوه فتبعا شبع بن بكري.","20:11":"ووقف عنده واحد من غلمان يوآب, فقال: «من سر بيوآب, ومن هو لداود, فوراء يوآب».","20:12":"وكان عماسا يتمرغ في الدم في وسط السكة. ولما رأى الرجل أن كل الشعب يقفون, نقل عماسا من السكة إلى الحقل وطرح عليه ثوبا, لما رأى أن كل من يصل إليه يقف.","20:13":"فلما نقل عن السكة عبر كل إنسان وراء يوآب لاتباع شبع بن بكري.","20:14":"وعبر في جميع أسباط إسرائيل إلى آبل وبيت معكة وجميع البيريين, فاجتمعوا وخرجوا أيضا وراءه.","20:15":"وجاءوا وحاصروه في آبل بيت معكة, وأقاموا مترسة حول المدينة فأقامت في الحصار, وجميع الشعب الذين مع يوآب كانوا يخربون لأجل إسقاط السور.","20:16":"فنادت امرأة حكيمة من المدينة: «اسمعوا. اسمعوا. قولوا ليوآب تقدم إلى ههنا فأكلمك».","20:17":"فتقدم إليها, فقالت المرأة: «أأنت يوآب؟» فقال: «أنا هو». فقالت له: «اسمع كلام أمتك». فقال: «أنا سامع».","20:18":"فتكلمت قائلة: «كانوا يتكلمون أولا قائلين: سؤالا يسألون في آبل. وهكذا كانوا انتهوا.","20:19":"أنا مسالمة أمينة في إسرائيل. أنت طالب أن تميت مدينة وأما في إسرائيل. لماذا تبلع نصيب الرب؟»","20:20":"فأجاب يوآب وقال: «حاشاي! حاشاي أن أبلع وأن أهلك.","20:21":"الأمر ليس كذلك. لأن رجلا من جبل أفرايم اسمه شبع بن بكري رفع يده على الملك داود. سلموه وحده فأنصرف عن المدينة». فقالت المرأة ليوآب: «هوذا رأسه يلقى إليك عن السور».","20:22":"فأتت المرأة إلى جميع الشعب بحكمتها فقطعوا رأس شبع بن بكري وألقوه إلى يوآب, فضرب بالبوق فانصرفوا عن المدينة كل واحد إلى خيمته. وأما يوآب فرجع إلى أورشليم إلى الملك.","20:23":"وكان يوآب على جميع جيش إسرائيل, وبنايا بن يهوياداع على الجلادين والسعاة,","20:24":"وأدورام على الجزية, ويهوشافاط بن أخيلود مسجلا,","20:25":"وشيوا كاتبا, وصادوق وأبياثار كاهنين,","20:26":"وعيرا اليائيري أيضا كان كاهنا لداود.","21:1":"وكان جوع في أيام داود ثلاث سنين, سنة بعد سنة, فطلب داود وجه الرب. فقال الرب: «هو لأجل شاول ولأجل بيت الدماء, لأنه قتل الجبعونيين».","21:2":"فدعا الملك الجبعونيين وقال لهم. والجبعونيون ليسوا من بني إسرائيل بل من بقايا الأموريين, وقد حلف لهم بنو إسرائيل, وطلب شاول أن يقتلهم لأجل غيرته على بني إسرائيل ويهوذا.","21:3":"قال داود للجبعونيين: «ماذا أفعل لكم؟ وبماذا أكفر فتباركوا نصيب الرب؟»","21:4":"فقال له الجبعونيون: «ليس لنا فضة ولا ذهب عند شاول ولا عند بيته, وليس لنا أن نميت أحدا في إسرائيل». فقال: «مهما قلتم أفعله لكم».","21:5":"فقالوا للملك: «الرجل الذي أفنانا والذي تآمر علينا ليبيدنا لكي لا نقيم في كل تخوم إسرائيل,","21:6":"فلنعط سبعة رجال من بنيه فنصلبهم للرب في جبعة شاول مختار الرب». فقال الملك: «أنا أعطي».","21:7":"وأشفق الملك على مفيبوشث بن يوناثان بن شاول من أجل يمين الرب التي بينهما, بين داود ويوناثان بن شاول.","21:8":"فأخذ الملك ابني رصفة ابنة أية اللذين ولدتهما لشاول: أرموني ومفيبوشث, وبني ميكال ابنة شاول الخمسة الذين ولدتهم لعدرئيل بن برزلاي المحولي,","21:9":"وسلمهم إلى يد الجبعونيين, فصلبوهم على الجبل أمام الرب. فسقط السبعة معا وقتلوا في أيام الحصاد, في أولها في ابتداء حصاد الشعير.","21:10":"فأخذت رصفة ابنة أية مسحا وفرشته لنفسها على الصخر من ابتداء الحصاد حتى انصب الماء عليهم من السماء, ولم تدع طيور السماء تنزل عليهم نهارا, ولا حيوانات الحقل ليلا.","21:11":"فأخبر داود بما فعلت رصفة ابنة أية سرية شاول.","21:12":"فذهب داود وأخذ عظام شاول وعظام يوناثان ابنه من أهل يابيش جلعاد الذين سرقوها من شارع بيت شان, حيث علقهما الفلسطينيون يوم ضرب الفلسطينيون شاول في جلبوع.","21:13":"فأصعد من هناك عظام شاول وعظام يوناثان ابنه, وجمعوا عظام المصلوبين,","21:14":"ودفنوا عظام شاول ويوناثان ابنه في أرض بنيامين في صيلع, في قبر قيس أبيه, وعملوا كل ما أمر به الملك. وبعد ذلك استجاب الله من أجل الأرض.","21:15":"وكانت أيضا حرب بين الفلسطينيين وإسرائيل, فانحدر داود وعبيده معه وحاربوا الفلسطينيين, فأعيا داود.","21:16":"ويشبي بنوب الذي من أولاد رافا, ووزن رمحه ثلاث مئة شاقل نحاس وقد تقلد جديدا, افتكر أن يقتل داود.","21:17":"فأنجده أبيشاي ابن صروية, فضرب الفلسطيني وقتله. حينئذ حلف رجال داود له قائلين: «لا تخرج أيضا معنا إلى الحرب, ولا تطفئ سراج إسرائيل».","21:18":"ثم بعد ذلك كانت أيضا حرب في جوب مع الفلسطينيين. حينئذ سبكاي الحوشي قتل ساف الذي هو من أولاد رافا.","21:19":"ثم كانت أيضا حرب في جوب مع الفلسطينيين. فألحانان بن يعري أرجيم البيتلحمي قتل جليات الجتي, وكانت قناة رمحه كنول النساجين.","21:20":"وكانت أيضا حرب في جت, وكان رجل طويل القامة أصابع كل من يديه ست, وأصابع كل من رجليه ست, عددها أربع وعشرون, وهو أيضا ولد لرافا.","21:21":"ولما عير إسرائيل ضربه يوناثان بن شمعى أخي داود.","21:22":"هؤلاء الأربعة ولدوا لرافا في جت وسقطوا بيد داود وبيد عبيده.","22:1":"وكلم داود الرب بكلام هذا النشيد في اليوم الذي أنقذه فيه الرب من أيدي كل أعدائه ومن يد شاول,","22:2":"فقال: «الرب صخرتي وحصني ومنقذي,","22:3":"إله صخرتي به أحتمي. ترسي وقرن خلاصي. ملجإي ومناصي. مخلصي, من الظلم تخلصني.","22:4":"أدعو الرب الحميد فأتخلص من أعدائي.","22:5":"لأن أمواج الموت اكتنفتني. سيول الهلاك أفزعتني.","22:6":"حبال الهاوية أحاطت بي. شرك الموت أصابتني."};
